/* [3a] DIBUAT OTOMATIS oleh tools/gen-npc-data.cjs dari design/narrative/npc/07a/07b/07c (+ 08 adegan Trust, 09 event romance, 10 hadiah). Jangan diedit langsung. */
const NPC_LINES = {"harjo":[{"c":{"at":"balai","t":0,"only":1},"s":"Monggo, Dok, pinarak. Mau urus surat, bayar pajak, atau cuma ngadem? Kipas di sini paling kencang se-kelurahan."},{"c":{"t":0,"only":1},"s":"Pripun, Dok, sudah kerasan? Sinyal di sini memang suka hilang. Tapi kalau kabar, cepat kok. Lewat Bu Ratna, nggih."},{"c":{"at":"balai","t":20},"s":"Laporan warga minggu ini: dua sumur kering, satu kambing hilang. Kambingnya sudah pulang sendiri, alhamdulillah."},{"c":{"t":20},"s":"Kata Bu Ratna klinik Dokter ramai. Itu kata Bu Ratna lho, nggih. Jadi ya… dibagi dua dulu, biar akurat."},{"c":{"at":"alun","t":20},"s":"Sore-sore saya keliling, Dok. Lampu jalan yang mati saya catat. Biar Mas Raka ndak lembur ngurusin lampu."},{"c":{"t":40},"s":"Gigi saya yang goyang sudah enakan, Dok. Kemarin saya berani makan kerupuk lagi. Kerupuk udang. Satu saja, nggih."},{"c":{"at":"lurah","t":40,"blok":"malam"},"s":"Sebentar lagi jam delapan, Dok, jadwal saya telepon istri. Kalau telat, gantian dia yang nelepon. Lebih lama."},{"c":{"t":40},"s":"Kakek Wiryo kemarin ngalahin saya catur lagi. Ya wajar, Dok, beliau guru saya. Murid kok menang, nanti kualat."},{"c":{"t":60},"s":"Dua tahun lagi saya pensiun, Dok. Nanti pagi-pagi saya mau tanda tangan apa, ya? Tanda tangan sarapan, mungkin."},{"c":{"t":80},"s":"Dok, nanti kalau saya sudah bukan lurah, saya tetap boleh mampir ke klinik, nggih? Bukan buat periksa. Buat ngobrol."},{"c":{"musim":"kemarau"},"s":"Kemarau begini kebun Bowo pasti kehausan. Dia ndak bakal minta, gengsinya tinggi. Nanti air tandon saya kirim diam-diam."},{"c":{"musim":"hujan"},"s":"Musim hujan itu musim rapat tanggul, Dok. Saya sudah hafal, kalau Mas Arya mulai garuk kepala, berarti airnya naik."},{"c":{"rain":1},"s":"Hujan-hujan begini enaknya kopi tubruk. Dokter mau? Di Balai Kota ada termos. Jarang yang tahu, nggih. Rahasia dinas."},{"c":{"stres":60},"s":"Dok, maaf, muka Dokter kok kelihatan capek. Ngurus kota itu juga begitu. Dikerjakan sendiri semua, ya ambruk."},{"c":{"event":"H60"},"s":"Malam ini Syukuran. Pidato saya tiga halaman. Kalau saya kepanjangan, Dokter batuk saja, nggih. Yang keras."}],
"ratna":[{"c":{"at":"warung","t":0,"only":1},"s":"Eh, ini dokter gigi yang baru itu, kan? Iya, kan? Duh, Ibu udah denger dari kemarin lusa, lho! Mau beli apa, Dok?"},{"c":{"t":0,"only":1},"s":"Dokter aslinya mana, sih? Metrapura? Pantesan putih, wong kerjanya di dalem ruangan terus. Eh, bercanda lho, Dok!"},{"c":{"at":"warung","t":20},"s":"Dok, Dok, sini! Katanya sih pipinya Pak Hasan Wetan bengkak segede bakpao. Katanya lho, ya. Ibu cuma nerusin."},{"c":{"at":"warung","t":20},"s":"Kulakan ke Tanjung Arum lagi? Salamin Koh Hendra, ya. Kalau di jalan bokek, ngutang sini juga boleh. Asal inget, lho."},{"c":{"t":20},"s":"Kak Tari tadi bikin roti pandan. Bilang aja disuruh Ibu, biasanya dikasih bonus. Biasanya, lho. Kalau Tari lagi baik."},{"c":{"at":"warung","t":40},"s":"Kemarin ada yang bilang klinik mahal. Langsung Ibu semprot: 'Mahal apa? Kamu aja yang pelit!' Diem dia. Hehe."},{"c":{"t":40},"s":"Bagus belum pulang dua minggu, Dok. Ujian, katanya. Ibu bilang, ujian ya ujian, makan jangan sampai lupa. Anak sekarang!"},{"c":{"at":"warung","t":40,"blok":"malam"},"s":"Pak Tono belum pulang, truknya masih nyangkut di Tanjung Arum. Warung sepi. Sini, Dok, duduk. Temenin Ibu ngobrol."},{"c":{"t":60},"s":"Dok… Ibu mau nanya. Perpustakaannya Mbak Sekar itu boleh didatengin orang tua, nggak? Cuma nanya. Cuma nanya, lho."},{"c":{"t":80},"s":"Dok, kemarin Ibu bisa baca tulisan di kaleng susu. Sendiri! 'Susu kental manis.' Aduh, jangan ketawa. Ibu bangga, nih."},{"c":{"musim":"kemarau"},"s":"Kemarau gini es teh laris manis. Gigi orang rusak, warung untung, Dokter juga untung. Kita kerja sama, ya, Dok. Hehe."},{"c":{"musim":"hujan"},"s":"Musim hujan, atap warung bocor dua titik. Udah Ibu taruh ember. Mas Arya katanya mau lihat. Katanya. Orangnya diem aja."},{"c":{"at":"warung","rain":1},"s":"Aduh, basah kuyup gitu! Sini, sini, neduh. Ibu bikinin teh anget. Gratis. Kali ini aja, jangan bilang-bilang, lho."},{"c":{"stres":60},"s":"Dok, mukanya pucet gitu. Udah makan belum? Nih, gorengan. Sekali-sekali dokter gigi juga boleh makan gorengan, kok."},{"c":{"event":"H45"},"s":"Lampionnya dari warung Ibu semua, lho! Eh, Dok, udah denger soal Pak Gunawan? Belum? Aduh, sini, sini…"}],
"darmi":[{"c":{"at":"jamu","t":0,"only":1},"s":"Hm."},{"c":{"t":0,"only":1},"s":"Dokter kota. Arep opo? Kunyit di pojok. Bayar di meja. Wis."},{"c":{"at":"jamu","t":20},"s":"Ini apa, Cah? …Temulawak. Bener. Hm. Besok Mbah tanya yang luwih angel."},{"c":{"t":20},"s":"Sirih itu buat gusi. Dokter juga pakai, to? Ya wis. Berarti kita satu perguruan."},{"c":{"at":"alun","t":20,"blok":"pagi"},"s":"Pasar Kamis. Beras kencur. Tuku siji. Mukamu kurang kencur, Cah."},{"c":{"at":"jamu","t":40},"s":"Bibit cengkeh wis ada. Ojo ditanam cedhak kunyit. Ndak akur. Kayak Mbah sama Ratna."},{"c":{"t":40},"s":"Wulan kemarin ngukur tensi Mbah. Katanya tinggi. Halah. Wong Mbah lagi nesu sama Bowo."},{"c":{"t":40},"s":"Sekar itu anak baik. Takon terus. Mbah seneng. Asal ndak takon yang wis Mbah jawab."},{"c":{"t":60},"s":"Dulu wong sakit gigi nyarinya Mbah. Sekarang Dokter. Ndak apa-apa. Sing penting waras."},{"c":{"t":80},"s":"Cah, nek Mbah wis ndak ada, buku catatan Mbah buat Sekar. Kowe sing mastikan. Ojo lali."},{"c":{"musim":"kemarau"},"s":"Kemarau. Herbamu disiram esuk, sebelum srengenge galak. Nek gosong, Mbah ndak tanggung."},{"c":{"musim":"hujan"},"s":"Musim hujan, sendi Mbah linu kabeh. Dokter punya obat sendi? Ndak? Ya wis. Jahe wae."},{"c":{"rain":1},"s":"Udan. Lungguh. Ombe iki. Ndak usah takon isine."},{"c":{"stres":60},"s":"Walah, Cah, raimu kok kusut kayak jarik durung disetrika. Iki, wedang serai. Diombe, terus turu. Ojo ngeyel."},{"c":{"event":"H10"},"s":"Ndak. Mbah ndak istirahat. Saben taun Mbah nandur siji buat Mbah Karto. …Ya wis. Teh sak gelas."}],
"dimas":[{"c":{"t":0,"only":1},"s":"…","a":"(Dimas lari ke belakang Bu Endang.)"},{"c":{"at":"sd","t":0,"only":1},"s":"Bu Sinta! Bu Sinta! Itu dokter! Mau nyuntik siapa? Bukan aku, kan? Aku udah mandi!"},{"c":{"t":20},"s":"Dok, di klinik ada robot nggak? Nggak ada? Kok nggak ada, sih? Beli dong, Dok. Satu aja. Yang kecil juga boleh."},{"c":{"at":"voli","t":20},"s":"Coach Doni tadi smash kenceng banget! Bolanya nyangkut di pohon! Dokter lihat nggak? Nggak? Yaaah."},{"c":{"at":"endang","t":20},"s":"Ssst, Ibu lagi jahit. Aku lagi gambar. Ini robot. Namanya… Robot Dok. Hehe. Mirip, kan? Mirip, dong."},{"c":{"t":40},"s":"Dok, tebak-tebakan! Gigi apa yang nggak bisa dicabut? …Gigi mundur! Hehe. Dari Pak Slamet. Lucu, kan? Kan?"},{"c":{"at":"sd","t":40},"s":"Tadi IPA, aku bilang ke Bu Sinta gigi hiu tumbuh terus. Bu Sinta bilang aku pinter. Pinter, Dok! Hehe."},{"c":{"t":40},"s":"Mas Arya ngajarin gambar pakai penggaris. Robotku jadi lurus! Lihat, lihat! …Kakinya miring dikit, sih."},{"c":{"t":60},"s":"Kemarin aku sikat gigi dua kali, Dok. Pagi sama malem. Ibu sampai kaget. Aku juga kaget, sih."},{"c":{"t":80},"s":"Dok, nanti kalau aku gede jadi dokter gigi, kliniknya sebelahan sama Dokter, ya? Biar istirahatnya bisa main bareng."},{"c":{"musim":"kemarau"},"s":"Panas bangeeet! Boleh beli es nggak? Satuuu aja. Nanti sikat gigi! Janji! Janji robot!"},{"c":{"musim":"hujan"},"s":"Hujan terus, nggak bisa nonton voli. Aku gambar robot payung. Mau lihat? Mau, dong. Ayo, mau aja."},{"c":{"at":"endang","rain":1},"s":"Ibu bilang jangan main air. Tapi airnya yang dateng ke sini. Bukan salahku, kan? Kan?"},{"c":{"stres":60},"s":"Dokter kok mukanya kayak Ibu kalau habis jahit sampai malem? Mau aku gambarin robot penghibur? Gratis, deh."},{"c":{"event":"K15"},"s":"Pameran Gigi Sehat! Aku mau ikut tebak-tebakan! …Kalau salah jawab, nggak disuntik, kan? Beneran?"}],
"endang":[{"c":{"at":"endang","t":0,"only":1},"s":"Oh, Dokter. Monggo, masuk. Maaf lho berantakan, kain di mana-mana. Ada perlu apa, Dok?"},{"c":{"t":0,"only":1},"s":"Maaf lho, Dok, Dimas tadi lari. Bukan karena Dokter, kok. Dulu ada… ya, kejadian. Nanti juga dia mau."},{"c":{"at":"endang","t":20},"s":"Ini kebaya pesanan Bu Lurah, payetnya tiga ratus. Ibu pasang satu-satu. Mata Ibu sampai juling, Dok. Hehe."},{"c":{"at":"warung","t":20,"blok":"pagi"},"s":"Pagi, Dok. Ibu beli gula sama benang. Iya, benang, di warung. Bu Ratna itu jual apa aja. Kabar juga ada, gratis malah."},{"c":{"t":20},"s":"Dimas cerita terus soal klinik. 'Dokternya nggak nyuntik, Bu, cuma lihat.' Matur nuwun, nggih, Dok. Beneran."},{"c":{"at":"endang","t":40},"s":"Dok, lingkar pinggang Dokter berapa? Eh, nggak, nggak apa-apa. Penjahit, kebiasaan. Maaf lho."},{"c":{"t":40},"s":"Mas Wahyu video call kemarin. Sebentar, sinyalnya putus-putus, mukanya kotak-kotak. Tapi Dimas senang. Ibu juga."},{"c":{"t":40},"s":"Bayarnya bulan depan nggak apa-apa, nggih? Atau Ibu jahitkan taplak buat klinik? Dokter suka warna apa?"},{"c":{"t":60},"s":"Kadang Ibu jahit sampai jam satu, Dok. Bukan karena kejar setoran. Kalau berhenti, pikiran Ibu ke mana-mana."},{"c":{"t":80},"s":"Dok, matur nuwun sudah jadi tetangga Ibu. Bukan dokter, lho. Tetangga. Buat Ibu, itu beda."},{"c":{"musim":"kemarau"},"s":"Pesta Rakyat udah deket. Kostum numpuk. Mata Ibu, tangan Ibu, dua-duanya lembur. Jarumnya untung nggak protes."},{"c":{"musim":"hujan"},"s":"Hujan begini kain susah kering, Ibu jemur di dalam. Rumah jadi kayak toko kain, Dok. Maaf lho kalau nyangkut di kepala."},{"c":{"rain":1},"s":"Lho, payung Dokter mana? Nih, bawa yang ini. Punya Mas Wahyu. Bolong dikit di pinggir, tapi masih bisa, kok."},{"c":{"stres":60},"s":"Dok, duduk dulu. Ibu bikinin teh. Kita ini sama-sama orang yang nggak bisa diem, ya. Lima menit aja, nggih."},{"c":{"event":"K55"},"s":"Kostum Pesta Rakyat tinggal dua! Dimas jadi robot. Iya, robot lagi. Dia maksa. Kardusnya minta Bu Ratna."}],
"bowo":[{"c":{"at":"kopi","t":0,"only":1},"s":"Ngapain ke sini? Ini kebun, bukan klinik. Nggak ada yang sakit gigi di sini. Kopinya juga nggak."},{"c":{"t":0,"only":1},"s":"Halah. Gigi saya sehat. Bapak saya umur delapan puluh, giginya masih lengkap. Nggak usah ditawarin."},{"c":{"at":"kopi","t":20},"s":"Itu yang merah dipetik. Yang ijo jangan. Dokter kota tahunya kopi itu asalnya dari gelas, to. Ya, to?"},{"c":{"at":"angkringan","t":20},"s":"Kopinya Slamet itu dari kebun saya. Makanya enak. Gulanya aja kebanyakan. Slamet itu ngeyel."},{"c":{"t":20},"s":"Mas Adji nyuruh nyimpen struk. Struk apa? Wong saya jualan pakai tangan, bukan pakai kertas. Halah."},{"c":{"at":"kopi","t":40},"s":"Nih. Kopi. Nggak usah bilang makasih. Nggak usah bilang Nadia juga, nanti dia minta. Wis, sana."},{"c":{"t":40},"s":"Mbah Darmi kemarin njewer saya lagi. Umur lima puluh delapan, Dok, masih dijewer. Gara-gara saya bilang jamunya pahit."},{"c":{"t":40},"s":"Kakak saya, Pak Lurah, mau periksa gigi ke Dokter? …Hm. Terserah dia. Saya sih nggak. Belum. Nggak."},{"c":{"t":60},"s":"Dulu Ningsih kecil suka ikut metik. Bijinya malah dimakan. Pahit, katanya. Tapi ketawa terus anaknya."},{"c":{"t":80},"s":"Dok. Kalau orang mau minta maaf, mulainya dari mana? Bukan buat saya. Buat… temen. Temen saya. Wis, jawab aja."},{"c":{"musim":"kemarau"},"s":"Bentar lagi panen. Kalau saya nggak kelihatan di angkringan, berarti saya di kebun. Nggak usah dicari."},{"c":{"musim":"hujan"},"s":"Hujan bagus buat kopi, jelek buat lutut. Dua-duanya punya saya. Halah, untung kopinya nggak bisa ngeluh."},{"c":{"at":"kopi","rain":1},"s":"Wis lah, neduh di gubuk. Ada kursi kecil itu, jangan diduduki. Itu… punya orang. Pokoknya jangan."},{"c":{"stres":60},"s":"Dokter kerja kayak saya waktu muda. Nanti tua lututnya bunyi kayak engsel pintu. Pulang sana. Tidur."},{"c":{"event":"K35"},"s":"Panen! Semua tangan dipakai! Dokter? …Halah, ya wis. Petik yang merah. Jangan dimakan."}],
"sinta":[{"c":{"at":"sd","t":0,"only":1},"s":"Selamat pagi, Dok. Saya Sinta, wali kelas tiga. Nah, ada waktu lima menit? Saya mau bahas UKS. Poinnya cuma tiga."},{"c":{"t":0,"only":1},"s":"Dokter baru, ya? Saya juga dulu 'guru baru'. Delapan tahun lalu. Sekarang dipanggilnya 'Bu Sinta yang galak'."},{"c":{"at":"sd","t":20},"s":"Hari ini tiga anak izin sakit gigi. Tiga, Dok. Dari dua puluh dua. Kalau ulangan, itu nilainya merah."},{"c":{"at":"perpus","t":20},"s":"Saya pinjam buku cerita buat kelas. Pilihan Mbak Sekar bagus-bagus. Dokter suka baca? Nah, nanti saya kasih daftar."},{"c":{"t":20},"s":"Nah, ini daftar anak yang belum pernah ke dokter gigi. Panjang. Jangan kaget, ya. Halaman duanya lebih panjang."},{"c":{"at":"sd","t":40},"s":"Tadi saya tanya 'siapa yang sikat gigi pagi ini', Dimas angkat tangan! Dimas, Dok! Saya hampir nangis di depan kelas."},{"c":{"t":40},"s":"Coach Doni minta jam olahraga ditambah. Saya bilang boleh, asal matematikanya juga. Langsung kabur dia. Larinya cepat."},{"c":{"at":"kedai","t":40},"s":"Hari Minggu saya di sini, koreksi PR. Nadia sudah hafal pesanan saya: teh, tanpa gula. Iya, Dok, lagi diet. Lagi."},{"c":{"t":60},"s":"Ibu saya telepon lagi semalam. Batuknya belum sembuh. Saya bilang bulan depan saya pulang. Sama kayak bulan lalu."},{"c":{"t":80},"s":"Dok, terima kasih sudah mau dengar soal surat itu. Saya belum cerita ke siapa pun. Bahkan ke Pak Wiryo."},{"c":{"musim":"kemarau"},"s":"Kemarau, anak-anak jajan es tiap istirahat. Mau saya larang, tapi saya juga beli. Satu. Jangan bilang murid saya, ya."},{"c":{"musim":"hujan"},"s":"Musim hujan, separuh kelas datang basah. Sepatunya dijemur di jendela. Kelas saya bau kaus kaki, Dok. Nah, begitulah."},{"c":{"at":"sd","rain":1},"s":"Hujan begini anak-anak susah fokus. Nah, saya ganti jadi jam cerita. Judulnya 'Kuman Gigi Kena Banjir'."},{"c":{"stres":60},"s":"Dok, saya guru. Saya hafal muka murid yang begadang. Dokter punya muka itu. Nah, pulang tepat waktu, ya? Ini PR."},{"c":{"event":"K15"},"s":"Pameran Gigi Sehat! Saya sudah siapkan dua puluh pertanyaan. Nah, Dokter jadi juri, ya. Jangan galak-galak."}],
"slamet":[{"c":{"at":"angkringan","t":0,"only":1},"s":"Monggo, monggo, Dok! Duduk. Wedang jahe? Kopi? Gorengan baru mentas dari wajan, masih kemebul."},{"c":{"t":0,"only":1},"s":"Lho, ini to dokter gigi yang baru? Monggo mampir angkringan. Bukanya sampai yang jaga ngantuk. Yang jaga saya."},{"c":{"at":"angkringan","t":20},"s":"Pesanan Dokter: wedang jahe, tahu isi dua. Bener, to? Dulu saya hafal trayek. Sekarang hafal pesanan."},{"c":{"t":20},"s":"Di angkringan nggak ada yang buru-buru, Dok. Jam dinding saya mati sejak buka. Sengaja. Biar pelanggan betah."},{"c":{"at":"alun","t":20,"blok":"pagi"},"s":"Belanja dulu, Dok. Cabai naik lagi. Nanti Mbak Yuni ngomel. Yang diomelin saya, cabainya diem aja."},{"c":{"at":"angkringan","t":40,"blok":"malam"},"s":"Tidurnya cukup, Dok? Jangan jawab 'cukup' kalau matanya merah kayak lampu rem. Saya mantan sopir, lho. Hafal."},{"c":{"t":40},"s":"Pak Bowo ngajak debat soal gula lagi. Katanya kopi jangan manis. Lha pelanggan saya sukanya manis. Seri, Dok."},{"c":{"at":"angkringan","t":40},"s":"Coach Doni, Mas Raka, Mas Ilham. Penumpang tetap angkringan ini. Orangnya itu-itu aja, ceritanya ganti terus."},{"c":{"t":60},"s":"Dok, kalau nanti saya jadi pasien, saya minum obat pengencer darah, lho. Dicatat, ya. Biar nggak salah belok."},{"c":{"t":80},"s":"Dok, saya dulu sopir bus malam. Remnya cuma dipakai kalau ada polisi. Jangan kerja kayak gitu, ya. Ngeri, lho."},{"c":{"musim":"kemarau"},"s":"Kemarau, malamnya enak, langit bersih. Habis dari sini mampir Bukit Bintang. Bintangnya gratis, nggak pakai karcis."},{"c":{"musim":"hujan"},"s":"Hujan, angkringan sepi. Tapi yang datang pasti penumpang setia. Dokter salah satunya. Nih, jahenya saya tambahin."},{"c":{"at":"angkringan","rain":1},"s":"Terpalnya bocor di pojok, Dok. Duduk sini aja. Pojok itu kursi VIP buat ember."},{"c":{"stres":60},"s":"Kopi ketiga? Wah, nggak, Dok. Saya turunin di halte wedang jahe aja. Penumpang ngantuk dilarang ngebut."},{"c":{"event":"Karaoke"},"s":"Malam Minggu! Siapa berani nyanyi duluan? Dokter? Ayo, ayo! Fals nggak apa-apa, yang penting pede!"}],
"tari":[{"c":{"at":"roti","t":0,"only":1},"s":"Pagi! Mau roti apa? Kismis, pandan, cokelat, keju. Eh, dokter gigi boleh makan roti manis, nggak? Hehe."},{"c":{"t":0,"only":1},"s":"Oh, ini dokter gigi baru itu! Aduh, saya jadi malu jualan roti manis. Eh, nggak, nggak, bercanda. Mampir, ya!"},{"c":{"at":"roti","t":20},"s":"Mas Adji udah ambil roti kismisnya. Jam setengah delapan pas. Jam dinding saya aja kalah tepat, hehe."},{"c":{"at":"roti","t":20},"s":"Ada roti baru! Roti jahe. Eh tapi… ada gulanya. Dikit. Dikiiit banget. Hampir nggak ada. Hehe."},{"c":{"at":"warung","t":20},"s":"Lagi ngobrol sama Bu Ratna. Rahasia. Eh, bukan rahasia! Cuma… resep. Iya, resep. Eh, beneran resep!"},{"c":{"at":"roti","t":40},"s":"Ayah tadi nyicip adonan saya. Katanya kurang garam. Ayah selalu bilang kurang garam. Tapi senyum, sih."},{"c":{"t":40},"s":"Nadia bilang kedainya lebih laris. Masa, sih? Ngopi tanpa roti itu kayak… eh, apa ya. Pokoknya nggak lengkap!"},{"c":{"t":40},"s":"Saya baca cerpen 'Telang' lagi di majalah. Bagus banget, Dok! Sepi, tapi anget. Kok bisa, ya, orang nulis kayak gitu?"},{"c":{"t":60},"s":"Dok, kalau saya bikin kue tanpa gula, Dokter mau jadi tukang cicip? Saya serius. Eh, setengah serius. Serius, deh."},{"c":{"t":80},"s":"Roti Senyum. Gimana namanya? Kalau jelek bilang, kalau bagus bilang juga. Pokoknya bilang, ya. Eh, jangan jelek."},{"c":{"musim":"kemarau"},"s":"Kemarau, mentega cepet leleh. Dapur kayak oven raksasa. Saya juga ikut ngembang. Eh, maksudnya kepanasan!"},{"c":{"musim":"hujan"},"s":"Musim hujan, roti anget laris. Orang neduh di sini sambil beli. Hujan itu rezeki tukang roti, hehe."},{"c":{"at":"roti","rain":1},"s":"Neduh dulu, Dok! Nih, roti sisa kemarin, masih enak kok. Gratis. Eh, jangan bilang Ayah, ya."},{"c":{"stres":60},"s":"Dok, makan dulu. Ini roti tanpa gula, beneran. Saya bikin buat Ayah. Satu buat Dokter. Ayah nggak usah tahu."},{"c":{"event":"K15"},"s":"Saya buka lapak kue di Pameran Gigi Sehat. Iya, saya tahu, ironis. Tapi tiap kue ada kartunya: 'Sikat gigi, ya!'"}],
"ilham":[{"c":{"at":"pos","t":0,"only":1},"s":"Selamat pagi, Dok! Kirim surat, ambil paket, atau cuma nanya? Nanya gratis, lho. Ongkirnya nol."},{"c":{"t":0,"only":1},"s":"Siap! Dokter yang di ruko Om Darto, kan? Jalan Alun-alun nomor tujuh. Saya hafal. Kode posnya juga."},{"c":{"at":"pos","t":20},"s":"Katalog Bahari Medika udah datang, Dok. Tebelnya kayak bantal. Ada stiker 'harga teman' dari Koh Hendra."},{"c":{"t":20},"s":"Hari ini nganter ke Dusun Atas. Nanjak terus, motor saya batuk-batuk. Kayaknya perlu ke klinik juga, Dok. Klinik motor."},{"c":{"at":"voli","t":20},"s":"Coach Doni bilang smash saya kurang tinggi. Padahal saya udah lompat sampai lupa alamat sendiri, Dok."},{"c":{"t":40},"s":"Ada kartu pos dari Laras, dari Tanjung Arum. Gambarnya laut. Dok, laut itu beneran biru, ya? Nggak diedit?"},{"c":{"at":"pos","t":40},"s":"Alat Dokter sampai besok pagi. Saya taruh paling atas di motor. Biar nggak kegencet karung berasnya Bu Ratna."},{"c":{"t":40},"s":"Adik saya mau masuk SMP. Seragamnya dijahit Bu Endang. Ibu saya nangis lihatnya. Saya? Nggak. Kelilipan aja."},{"c":{"t":60},"s":"Dok… kapan-kapan mampir Kantor Pos, ya. Ada yang mau saya kasih. Bukan paket. Ya, semacam paket. Nanti aja."},{"c":{"t":80},"s":"Kalau ke Tanjung Arum lagi, saya boleh ikut? Bekal bawa sendiri. Saya cuma pengin lihat laut. Sekali aja."},{"c":{"musim":"kemarau"},"s":"Kemarau, jalan desa debunya tebel. Pulang-pulang saya kayak donat ditaburin gula halus. Kak Tari pasti seneng."},{"c":{"musim":"hujan"},"s":"Hujan, Dok! Tapi surat harus sampai. Jas hujan saya bolong tiga. Suratnya aman, yang basah saya. Siap!"},{"c":{"rain":1},"s":"Siap, basah! Lho, Dokter juga? Wah, kita senasib. Bedanya, saya digaji buat basah. Hehe."},{"c":{"stres":60},"s":"Dok, ada surat buat Dokter. Pengirimnya: badan Dokter sendiri. Isinya cuma satu kata: 'Tidur.' Hehe, saya karang."},{"c":{"event":"H10"},"s":"Dua ratus polybag bibit, Dok! Motor saya jadi kebun berjalan. Mau saya anter sekalian ke Lereng?"}],
"wiryo":[{"c":{"at":"alun","t":0,"only":1},"s":"Oh. Duduk, Nak. Kamu keponakannya Darto, to? Dari jauh kelihatan. Jalannya sama, agak miring ke kiri."},{"c":{"t":0,"only":1},"s":"Selamat datang, Nak. Kota ini kecil. Separuhnya murid saya. Separuhnya lagi orang tua murid saya. Hehe."},{"c":{"at":"alun","t":20},"s":"Main? Ndak usah bisa. Duduk saja, saya gerakkan dua-duanya. Darto dulu juga begitu. Kalah terus, tapi senang."},{"c":{"t":20},"s":"Kemarin Ilham bawakan teh. Anak itu dulu paling ribut di kelas, Nak. Sekarang paling rajin. Lucu, to?"},{"c":{"at":"wiryo","t":20},"s":"Ini foto Asih, tahun tujuh lima. Yang motret bapaknya Laras. Cantik, to? Saya dulu nekat, Nak. Untung diterima."},{"c":{"at":"alun","t":40},"s":"Sariawan saya sudah sembuh. Gigi palsunya saya rendam dulu di gelas. Makan bubur. Enak, ndak usah ngunyah."},{"c":{"t":40},"s":"Harjo kemarin kalah lagi. Jangan bilang saya cerita, ya. Dia itu sensitif. Dari SD. Dulu nangis gara-gara PR."},{"c":{"t":40},"s":"Tadi saya mau bilang apa, ya… Sebentar. …Oh. Sudah makan, Nak? Iya. Itu. Itu yang mau saya tanya."},{"c":{"t":60},"s":"Namamu saya tulis di buku saku ini, Nak. Di halaman yang paling sering saya buka. Biar ndak lupa."},{"c":{"t":80},"s":"Kalau nanti saya mulai lupa banyak hal, kamu ingatkan saya soal Darto, ya. Dia itu lucu. Jangan sampai hilang."},{"c":{"musim":"kemarau"},"s":"Kemarau, bidak caturnya panas kena matahari. Kalau mau pegang kuda, pakai sapu tangan. Kudanya galak."},{"c":{"musim":"hujan"},"s":"Hujan. Ndak ke alun-alun. Main di rumah saja, Nak. Papan cadangan ada di lemari. Papannya Darto."},{"c":{"at":"wiryo","rain":1},"s":"Duduk, Nak. Dengar hujan di genteng. Asih dulu suka bunyi ini. Katanya kayak tepuk tangan pelan."},{"c":{"stres":60},"s":"Nak, dulu murid saya yang belajar sampai subuh nilainya ndak lebih bagus. Cuma matanya yang lebih merah. Tidur sana."},{"c":{"event":"H45"},"s":"Lampion saya dua. Satu buat Asih, satu buat Darto. Kamu mau pegang yang buat Darto? Dia pasti senang."}],
"doni":[{"c":{"at":"voli","t":0,"only":1},"s":"Hei, Dokter baru! Ayo main! Kalah traktir es teh! Nggak bisa? Nggak apa-apa! Belajar sambil kalah! Gas!"},{"c":{"t":0,"only":1},"s":"Dok! Push-up sehari berapa kali? Nol?! Waduh, waduh. Tenang, nanti kita perbaiki. Gas!"},{"c":{"at":"voli","t":20},"s":"Lututnya ditekuk, Dok! Bukan gitu! Itu kayak jongkok nunggu angkot! Yang semangat, dong!"},{"c":{"at":"sd","t":20},"s":"Lagi ngajar olahraga. Bu Sinta bilang jam saya kepanjangan. Saya bilang otak juga butuh lari. Saya malah dikasih PR."},{"c":{"t":20},"s":"Dimas sekarang asisten pungut bola. Gajinya es teh. Rajinnya ngalahin pemain saya. Pemain saya harusnya malu!"},{"c":{"at":"voli","t":40},"s":"Smash Andre makin bagus. Tapi kalau bola ke muka, dia masih merem. …Nanti saya urus. Pasti saya urus."},{"c":{"at":"angkringan","t":40},"s":"Mas Raka nyanyi dangdut kemarin. Fals parah! Tapi semangatnya juara satu. Mirip saya kalau servis. Hahaha!"},{"c":{"t":40},"s":"Tadi pagi lari lima kilo, Dok! Lutut bunyi kretek-kretek kayak kerupuk kena angin. Tapi tetep gas, dong!"},{"c":{"t":60},"s":"Kadang habis anak-anak pulang saya duduk di sini, lihatin net. Mikir, coba dulu lutut ini nggak rusak. Ah, udahlah."},{"c":{"t":80},"s":"Dok, ini peluit cadangan saya. Buat Dokter. Kalau pasiennya bandel, tiup. Hahaha! Nggak, nggak. Buat kenang-kenangan."},{"c":{"musim":"kemarau"},"s":"Kemarau, lapangan keras, bolanya mantul tinggi. Enak buat smash, nggak enak buat lutut. Ah, gas aja!"},{"c":{"musim":"hujan"},"s":"Hujan, latihan pindah ke dalam. Lari di tempat, push-up. Anak-anak benci. Saya seneng. Hahaha!"},{"c":{"rain":1},"s":"Lapangan basah, hari ini nggak ada latihan bola. Dulu saya paksa. …Sekarang nggak lagi. Nggak lagi."},{"c":{"stres":60},"s":"Dok, ikut lari sore! Sepuluh menit aja! Keringat itu buang stres. Kata saya, lho, bukan kata dokter. Hahaha!"},{"c":{"event":"K55"},"s":"Turnamen Pesta Rakyat! Kita lawan Desa Wetan! Dokter jadi dokter tim, ya? Bawa plester yang banyak! Gas!"}],
"adji":[{"c":{"at":"adji","t":0,"only":1},"s":"Halo! Klien baru? Bukan? Oh, dokter baru! Wah, sama-sama baru. Kopi? Aku punya tiga, bayaran klien. Ambil, ambil."},{"c":{"at":"roti","t":20,"blok":"pagi"},"s":"Roti kismis. Tiap hari. Jangan dihakimi, ya. Mau satu? Aku traktir. Anggap aja investasi pertemanan. Bunganya nol."},{"c":{"at":"adji","t":20},"s":"Pajak klinik bulan ini aman, udah aku cek dua kali. Tiga, sih. Empat kalau dihitung yang sambil makan."},{"c":{"at":"kedai","t":40},"s":"Kopi susu gula aren. Nadia udah nggak nanya, lihat mukaku langsung bikin. Kayak sulap. Sulap yang ada tagihannya."},{"c":{"t":40},"s":"Bu Ratna nyodorin foto keponakannya lagi. Ketiga kalinya bulan ini. Aku pura-pura ditelepon. Padahal HP-ku mati. Hahaha."},{"c":{"at":"angkringan","t":60},"s":"Raka menang gaple lagi. Curang dia. Eh, nggak deng. Aku aja yang mikirnya kelamaan. Kebiasaan ngitung. Hahaha."},{"c":{"h":20},"s":"Kamu udah makan? Eh, aku nanya bukan karena kebiasaan, lho. Ya, kebiasaan juga sih. Tapi yang ini beda. Dikit. Hehe."},{"c":{"h":50},"s":"Tadi aku latihan nyapa kamu di depan kaca. Lima kali. Kacanya sampai bosen. …Eh, selamat pagi. Nah, gitu doang sih."},{"c":{"at":"adji","h":50},"s":"Nita nanya di grup, 'Mas, lagi deket sama siapa?' Aku jawab 'Sama kalkulator.' Mereka nggak percaya. Pinter juga, ya."},{"c":{"h":70},"s":"Kalau aku tiba-tiba diem, bukan bosen, ya. Aku lagi nyusun kalimat yang nggak bikin aku kedengeran bego. Belum ketemu."},{"c":{"pacaran":1},"s":"Ibuku nanya kamu suka masakan apa. Aku bilang belum tahu, terus dimarahin. Jadi… kamu suka masakan apa? Ini darurat."},{"c":{"at":"kedai","pacaran":1},"s":"Nadia ngelihatin kita dari balik mesin kopi. Senyumnya nyebelin banget. Aku suka, sih. Jangan bilang dia."},{"c":{"at":"rumahku","nikah":1,"blok":"pagi"},"s":"Pagi! Laporan: sarapan siap, kopi anget, aku udah ganteng. Poin terakhir masih menunggu hasil audit. Hahaha."},{"c":{"nikah":1},"s":"Ibu telepon. Bukan nyari aku, nyari kamu. Aku diturunin pangkat jadi operator telepon. Gajinya nol, lho."},{"c":{"renggang":1},"s":"Oh. Hai. Aku… nggak apa-apa, kok. Kerjaan lagi numpuk. Nanti aku kabarin, ya."},{"c":{"musim":"kemarau"},"s":"Kemarau gini aku haus terus. Kopi nggak ngebantu, air putih ngebantu. Aku tahu. Aku cuma nggak mau. Hahaha."},{"c":{"rain":1},"s":"Hujan. Struk klien basah semua. Aku jemur pakai jepitan baju. Kantorku sekarang kayak laundry kiloan."},{"c":{"stres":60},"s":"Duduk dulu. Aku bukan dokter, tapi aku bisa ngitung jam kerjamu. Hasilnya defisit. Defisit tidur. Parah."},{"c":{"event":"K15"},"s":"Pameran Gigi Sehat! Aku jaga meja pendaftaran. Rapi kayak neraca. Mampir, ya. Ada permen. Eh, permen bebas gula!"}],
"arya":[{"c":{"at":"teknik","t":0,"only":1},"s":"Ya?"},{"c":{"t":0,"only":1},"s":"…Sore."},{"c":{"at":"proyek","t":20,"proyek":1},"s":"Fondasinya miring dua senti. Harus dibongkar. Nggak apa-apa. Mending sekarang daripada nanti."},{"c":{"at":"perpus","t":20},"s":"…Hai.","a":"(Arya mengangkat buku sedikit, tanda sapaan, lalu lanjut membaca.)"},{"c":{"t":40},"s":"Retak di klinikmu udah aku cek lagi. Stabil. Kalau dindingnya bunyi aneh, bilang. Jangan didiemin."},{"c":{"at":"teknik","t":40},"s":"Dimas tadi ke sini. Gambar robotnya sekarang pakai skala. Satu banding sepuluh. …Aku bangga. Dikit."},{"c":{"at":"bukit","t":60,"blok":"malam"},"s":"Dari sini jembatannya kelihatan. Lampunya tiga, satu mati. Besok aku ganti. Udah aku catat."},{"c":{"t":60},"s":"Raka bilang aku kayak tembok. Aku bilang tembok itu berguna. Dia ketawa sampai batuk. Aku nggak ngerti lucunya di mana."},{"c":{"h":20},"s":"Kamu suka jendela yang menghadap timur atau barat? …Nggak. Cuma nanya. Buat… data."},{"c":{"h":50},"s":"Biasanya aku nggak ngobrol selama ini. Ini udah tujuh menit. Aku hitung. …Nggak apa-apa. Aku nggak keberatan."},{"c":{"at":"bukit","h":70,"blok":"malam"},"s":"Sama kamu, diem pun nggak canggung. Sama orang lain, aku harus mikir mau ngomong apa. Capek."},{"c":{"pacaran":1},"s":"Aku gambar kamu kemarin. Nggak mirip. Hidungnya kayak denah. Jangan dilihat. …Ya udah, lihat. Sebentar."},{"c":{"at":"teknik","pacaran":1},"s":"Duduk sini. Kursinya udah aku stel. Tingginya pas buat kamu. Aku ukur pas kamu nggak lihat."},{"c":{"at":"rumahku","nikah":1,"blok":"pagi"},"s":"Pagi. Engsel pintu belakang udah aku betulin. Udah nggak bunyi. Kopi di meja."},{"c":{"nikah":1},"s":"Ibu kirim sayur dari Kampung Kali. Banyak. Katanya kamu terlalu kurus. Aku bilang ukuranmu pas."},{"c":{"renggang":1},"s":"…Iya."},{"c":{"musim":"hujan"},"s":"Musim hujan, kalau tanggul siaga aku tidur di kantor. Jangan khawatir. Ada kasur lipat. Sama termos."},{"c":{"rain":1},"s":"Air di selokan alun-alun dua belas senti. Masih aman. Jam sembilan aku cek lagi."},{"c":{"stres":60},"s":"Kamu tidur berapa jam? …Empat? Itu di bawah standar. Standar siapa? Standarku. Pulang."},{"c":{"event":"H10"},"s":"Lubangnya tiap tiga meter. Yang dekat tebing jangan dulu. Kalau naik, pakai sepatu. Tolong."}],
"raka":[{"c":{"at":"polisi","t":0,"only":1},"s":"Selamat siang! Ada yang bisa dibantu? Lapor kehilangan? Lapor rindu? Yang kedua bukan wewenang saya, ya."},{"c":{"t":0,"only":1},"s":"Oh, dokter baru! Selamat datang di Rimbasari. Kasus terberat di sini: kambing kabur sama jemuran ketuker."},{"c":{"at":"polisi","t":20},"s":"Laporan hari ini: Pak Kedip, lampu jalan di Jalan Niaga, masih kedip-kedip. Pelapornya Laras. Lagi."},{"c":{"t":20,"patroli":1,"blok":"malam"},"s":"Patroli! Gembok warung aman, angkringan aman, Dokter… aman? Aman. Siap, lanjut."},{"c":{"at":"voli","t":40},"s":"Kata Coach Doni servis saya kayak surat tilang. Nyasar ke mana-mana, tapi pasti nyampe. Itu pujian, kan?"},{"c":{"at":"angkringan","t":40},"s":"Gaple sama Adji. Dia mikirnya kelamaan, saya nunggu sambil ngabisin tiga gorengan. Yang rugi dompet saya."},{"c":{"t":60},"s":"Kakak saya naik pangkat kemarin. Ayah telepon semua orang. Kecuali saya. Ya udah, saya ucapin sendiri. Lewat WA."},{"c":{"t":60,"patroli":1,"blok":"malam"},"s":"Kota sepi gini enak buat mikir. Di Metrapura mikir aja nggak sempat. Di sini malah kebanyakan, Dok."},{"c":{"h":20},"s":"Dok, saya mau lapor. Hari ini saya senyum tujuh kali. Lima kali pas ketemu Dokter. Mencurigakan. Saya selidiki."},{"c":{"h":50},"s":"Kalau saya nggak bercanda, Dokter nggak kabur, kan? Lagi saya coba, nih. Ngomong serius. Ternyata susah, ya."},{"c":{"h":70,"patroli":1,"blok":"malam"},"s":"Ikut patroli lagi? Rutenya sama. Tapi kalau bareng Dokter, kok rasanya jalannya kependekan, ya."},{"c":{"pacaran":1},"s":"Mulai hari ini klinik masuk daftar patroli prioritas. Alasan resmi: keamanan. Alasan asli: rahasia negara."},{"c":{"at":"angkringan","pacaran":1},"s":"Doni nanya kenapa saya nggak nyanyi dangdut lagi. Saya bilang sekarang nyanyinya dalam hati. Dia pura-pura muntah."},{"c":{"at":"rumahku","nikah":1,"blok":"pagi"},"s":"Siap, Komandan! Sarapan di meja, sepatu udah disemir, lencana udah dilap. Laporan selesai. Mohon petunjuk."},{"c":{"nikah":1},"s":"Ayah telepon tadi. Nanyain kamu. Nanyain saya juga, dikit. Ada kemajuan, Komandan."},{"c":{"renggang":1},"s":"Siap. Saya lagi banyak tugas. Nanti saya mampir. …Kalau boleh."},{"c":{"musim":"kemarau"},"s":"Kemarau, laporan paling banyak: rebutan air sumur. Saya sekarang juru damai sumur. Jabatan baru, gaji lama."},{"c":{"rain":1},"s":"Hujan, patroli tetap jalan. Jas hujan saya oranye. Kata Laras kayak jeruk berjalan. Jeruk yang bertugas."},{"c":{"stres":60},"s":"Dok, saya tilang. Pelanggaran: kerja ngebut. Sanksi: duduk di angkringan sepuluh menit. Nggak ada damai."},{"c":{"event":"H45"},"s":"Malam Lampion. Saya jaga keamanan. Tapi kalau Dokter mau lepas lampion, saya bisa izin lima menit. Sepuluh juga bisa."}],
"galih":[{"c":{"at":"puskes","t":0,"only":1},"s":"Selamat siang, Dokter. Ada rujukan yang mau dibahas? Silakan duduk. Tehnya masih hangat."},{"c":{"t":0,"only":1},"s":"Selamat datang di Rimbasari. Kalau butuh data pasien, Puskesmas terbuka. Asal lewat prosedur. Maaf, saya memang begini."},{"c":{"at":"puskes","t":20},"s":"Tensi Pak Hasan seratus enam puluh lagi. Saya sudah tegur tiga kali. Mungkin Dokter bisa jadi yang keempat."},{"c":{"at":"perpus","t":20},"s":"Saya sedang baca buku puisi. Tolong jangan tanya penyairnya. Kalau Dokter kenal, saya malu."},{"c":{"at":"kedai","t":40},"s":"Teh. Selalu teh. Nadia sudah berhenti menawari saya kopi. Saya lega, sebenarnya. Dia gigih sekali."},{"c":{"t":40},"s":"Mbah Darmi kemarin memberi saya jamu. Rasanya… pahit sekali. Saya habiskan. Saya takut ditanya isinya apa."},{"c":{"t":60,"jaga":1,"blok":"malam"},"s":"Malam ini sepi. Saya suka kalau sepi. Artinya tidak ada yang sakit. Atau semua sedang menahan. Semoga yang pertama."},{"c":{"t":60},"s":"Dulu saya pernah dua hari tidak tidur. Saya kira itu keren. Sekarang saya tahu, itu cuma bikin tangan gemetar."},{"c":{"h":20},"s":"Saya menulis sesuatu tadi pagi. Di balik kertas resep. …Bukan resep. Tolong lupakan saya bilang itu."},{"c":{"h":50},"s":"{nama}. …Maaf, saya tidak biasa memanggil nama. Tapi rasanya lebih pas daripada 'Dokter'. Boleh, kan?"},{"c":{"at":"bukit","h":70},"s":"Di sini saya tidak menghitung apa-apa. Detak, dosis, jam. Bintangnya juga tidak. Lega rasanya."},{"c":{"pacaran":1},"s":"Saya tidur enam jam kemarin. Enam. Wulan sampai memeriksa nadi saya. Katanya saya sakit."},{"c":{"pacaran":1,"jaga":1,"blok":"malam"},"s":"Terima kasih sudah mampir. Tehnya dua. Satu untukmu. Sudah saya hitung. Dua kali."},{"c":{"at":"rumahku","nikah":1,"blok":"pagi"},"s":"Selamat pagi. Puisi di meja itu untukmu. Jangan dibaca keras-keras, ya. Dari dapur kedengaran."},{"c":{"nikah":1},"s":"Ibu menelepon. Katanya kamu harus makan sayur lebih banyak. Saya bilang, 'Bu, dia dokter.' Ibu tidak peduli."},{"c":{"renggang":1},"s":"Baik. Saya mengerti. Saya tunggu. Kalau soal menunggu, saya cukup terlatih."},{"c":{"musim":"hujan"},"s":"Musim hujan, kasus demam berdarah naik. Saya di Puskesmas lebih lama. Kalau pesanmu lama saya balas, itu sebabnya."},{"c":{"rain":1},"s":"Hujan. Saya suka bunyinya di atap Puskesmas. Jaga malam jadi tidak terlalu sepi."},{"c":{"stres":60},"s":"Saya kenal tanda itu. Mata, bahu, cara bernapas. Dulu saya juga begitu. Duduk sebentar. Saya ukur tensimu."},{"c":{"event":"H25"},"s":"Bakti Sosial. Kita berbagi meja. Pasien gigi ke kamu, tensi ke saya. Kalau saya salah meja, tegur saja."}],
"sekar":[{"c":{"at":"perpus","t":0,"only":1},"s":"Selamat… eh, selamat sore. Mau pinjam buku? Kartunya… anu… ada di meja. Maaf, maaf."},{"c":{"at":"bunga","t":0,"only":1,"blok":"pagi"},"s":"Oh! Maaf, saya nggak lihat ada orang. Saya lagi… ngobrol sama bunga. Eh, bukan. Nggak. Lupakan, ya."},{"c":{"at":"perpus","t":20},"s":"Ada buku baru dari Tanjung Arum, kiriman Tante Lies. Satu soal gigi. Anu… saya simpankan buat Dokter."},{"c":{"t":20},"s":"Pak Wiryo datang tiap Minggu pagi. Duduknya selalu di kursi dekat jendela. Nggak pernah saya kasih ke orang lain."},{"c":{"at":"bunga","t":40},"s":"Telangnya mekar tiga. Kemarin dua. Saya hitung tiap pagi. Iya, saya tahu… agak aneh. Maaf."},{"c":{"at":"jamu","t":40},"s":"Senin saya di sini. Mbah Darmi ngajarin nama daun. Saya salah terus. Mbah bilang 'Hm.' Itu artinya bagus, kok."},{"c":{"t":60},"s":"Kak Tari bilang suka cerita 'Telang'. Saya hampir bilang… anu, nggak jadi. Belum."},{"c":{"at":"perpus","t":60,"blok":"malam"},"s":"Bu Ratna mampir tadi. Lama lihat-lihat rak buku anak. Nggak pinjam apa-apa. Saya juga nggak nanya."},{"c":{"h":20},"s":"Saya selipkan pembatas di buku yang Dokter pinjam. Kelopak telang. Jangan dibuang, ya. Eh, terserah, sih."},{"c":{"h":50},"s":"Biasanya saya baca sendirian. Tapi sekarang kalau ketemu bagian lucu, saya jadi pengin… cerita ke kamu. Anu, gitu."},{"c":{"at":"bunga","h":70},"s":"Ini bedeng baru. Masih kosong. Saya… sisakan buat bunga yang kamu suka. Kalau mau pilih. Kalau mau."},{"c":{"pacaran":1},"s":"Semalam saya nulis lagi. Tokoh baru. Dokter gigi. Jangan geer, ya. Dia… cuma agak mirip. Agak."},{"c":{"at":"perpus","pacaran":1},"s":"Kursi dekat jendela punya Pak Wiryo. Kursi sebelah saya sekarang punya kamu. Peraturan perpustakaan baru."},{"c":{"at":"rumahku","nikah":1,"blok":"pagi"},"s":"Teh telang di meja. Kalau dikasih jeruk nipis, warnanya jadi ungu. Saya tahu kamu tahu. Saya cuma suka bilang."},{"c":{"nikah":1},"s":"Rak buku kita udah penuh. Saya mau minta tolong Mas Arya bikinin satu lagi. Atau dua. Boleh, ya?"},{"c":{"renggang":1},"s":"Oh. Iya. Nggak apa-apa. Saya… ada di perpustakaan, kalau mau."},{"c":{"musim":"kemarau"},"s":"Kemarau, kebunnya haus. Saya bangun lebih pagi buat nyiram. Bunganya seger. Sayanya ngantuk."},{"c":{"at":"perpus","rain":1},"s":"Hujan, perpustakaan jadi ramai. Orang neduh, terus nggak sengaja baca. Makanya saya suka hujan. Hehe."},{"c":{"stres":60},"s":"Kamu… kelihatan capek. Duduk sebentar di sini, ya. Nggak usah baca. Duduk aja. Perpustakaan juga boleh buat itu."},{"c":{"event":"H10"},"s":"Bibitnya… nggak apa-apa. Raknya roboh semalam. Sebagian selamat. Sebagian. Saya nggak apa-apa, kok."}],
"nadia":[{"c":{"at":"kedai","t":0,"only":1},"s":"Halo, pelanggan baru! Cobain, gratis! Kopi Pak Bowo, aku seduh pakai V60. Gimana? Gimana? Asemnya enak, kan?"},{"c":{"at":"kedai","t":20},"s":"Juri resmi datang! Racikan hari ini: kopi plus kayu manis. Jujur, ya. Mas Adji bilang enak terus. Nggak dihitung."},{"c":{"at":"kopi","t":20,"blok":"pagi"},"s":"Eh! Ngapain jam segini? Aku? Aku… olahraga. Iya, olahraga metik kopi. Jangan bilang siapa-siapa, ya!"},{"c":{"at":"kedai","t":40},"s":"Kemarin pelanggan cuma sembilan. Tapi sembilan itu naik dari tujuh, lho! Naik dua! Aku rayain pakai espresso."},{"c":{"t":40},"s":"Kak Tari bilang tokonya lebih laris. Ya iyalah, roti nggak butuh teori. Kopi butuh! Ada ilmunya! Oke, kita seri."},{"c":{"at":"kedai","t":60,"blok":"malam"},"s":"Jam sepuluh, kedai sepi, aku suka duduk di lantai belakang bar. Ubinnya adem. Jangan ketawa, ya."},{"c":{"t":60},"s":"Mama nanya lagi kapan aku 'pulang beneran'. Aku bilang aku udah pulang. Mama belum ngerti. Belum, ya. Nanti juga."},{"c":{"h":20},"s":"Ini cangkir favoritku, nggak pernah aku pakai buat pelanggan. Hari ini aku pakai. Buat kamu. Udah, minum!"},{"c":{"h":50},"s":"Aku capek, tahu. Tapi kalau kamu dateng, capeknya ilang separuh. Sisanya ilang kalau kamu ketawa. Gombal? Biarin."},{"c":{"at":"kedai","h":70},"s":"Jangan bilang siapa-siapa, ya. Aku tuh di depan orang sok semangat terus. Sama kamu doang aku berani lemes gini."},{"c":{"pacaran":1},"s":"Aku lagi ngulik racikan baru. Kali ini kamu nggak dapet duluan. Kamu yang terakhir. Soalnya yang terakhir paling enak."},{"c":{"at":"kopi","pacaran":1,"blok":"pagi"},"s":"Tadi Pak Bowo nanya, 'Dokter itu baik sama kamu?' Aku bilang iya. Dia cuma 'Hm.' Terus senyum. Pak Bowo senyum, lho!"},{"c":{"at":"rumahku","nikah":1,"blok":"pagi"},"s":"Bangun, bangun! Kopi pertama hari ini, khusus buat kamu. Rasanya? Jangan jawab 'enak'. Aku mau detail!"},{"c":{"nikah":1},"s":"Mama telepon, minta dikirimin kopi 'yang kemarin itu'. Mama! Minta kopi! Dari aku! Aduh, aku mau nangis."},{"c":{"renggang":1},"s":"Oke! Oke. Kedai lagi rame, kok. Aku sibuk. Nggak apa-apa. Nanti aja ngobrolnya."},{"c":{"musim":"kemarau"},"s":"Kemarau, panen kopi! Seminggu ke depan aku bakal bau kopi. Lebih bau dari biasanya. Maaf duluan, ya!"},{"c":{"at":"kedai","rain":1},"s":"Hujan, kedai sepi. Tapi kamu dateng. Itu namanya pelanggan setia. Atau nekat. Dua-duanya aku suka."},{"c":{"stres":60},"s":"Stop. Duduk. Ini bukan kopi, ini cokelat panas. Kafeinmu hari ini udah kebanyakan. Nggak ada protes. Minum."},{"c":{"event":"K35"},"s":"Panen! Aku bawa termos kopi buat semua pemetik. Pak Bowo pura-pura nggak mau. Udah habis dua gelas, tuh."}],
"laras":[{"c":{"at":"studio","t":0,"only":1},"s":"Selamat datang di Studio Lensa! Pas foto? Foto keluarga? Foto… eh, dokter baru! Tahan! Klik. Makasih!"},{"c":{"t":0,"only":1,"keliling":1},"s":"Jangan gerak! …Udah. Cahayanya pas banget di belakang Dokter. Nanti aku cetak, ya. Gratis, kok."},{"c":{"at":"bukit","t":20,"keliling":1},"s":"Jam segini cahayanya paling cakep. Orang bilang golden hour. Aku nyebutnya jam madu. Lebih manis, kan?"},{"c":{"at":"studio","t":20},"s":"Bapak lagi tidur siang. Nanti kalau bangun pasti nanya 'Siapa itu?', terus kenalan tiga kali. Maklumin, ya."},{"c":{"t":40},"s":"Pak Kedip masih kedip! Udah aku lapor Mas Raka empat kali. Katanya Pak Kedip itu 'saksi kunci'. Saksi apa coba?"},{"c":{"at":"alun","t":40},"s":"Lagi motret Kakek Wiryo main catur. Kalau tahu ada kamera, beliau langsung pose. Kudanya diangkat tinggi-tinggi."},{"c":{"t":60},"s":"Mata Bapak makin buram. Kemarin pegang foto Ibu, terus bilang 'Ini ibumu, ya?' Iya, Pak. Iya."},{"c":{"at":"studio","t":60},"s":"Aku punya arsip foto satu kota. Kotak-kotak di belakang. Kadang aku buka satu, terus nangis. Nggak apa-apa, kok."},{"c":{"h":20},"s":"Aku foto kamu lagi. Sengaja. Sekarang aku nggak minta maaf. Kamu fotogenik. Itu salah kamu sendiri."},{"c":{"h":50},"s":"Cuma kamu yang ngarahin kamera ke aku dan aku nggak kabur. Gitu aja. Pengin kamu tahu."},{"c":{"h":70,"keliling":1},"s":"Kalau kamu ikut keliling, fotoku jelek semua. Fokusnya ke kamu terus, objeknya kelewat."},{"c":{"pacaran":1},"s":"Foto kita aku pajang di studio. Di pojok, kecil. Tapi pelanggan pertama langsung nanya. Hehe, ketahuan."},{"c":{"at":"studio","pacaran":1},"s":"Kata Bapak, 'Suaramu beda kalau dia dateng.' Bapak nggak bisa lihat, tapi bisa denger. Curang, ih."},{"c":{"at":"rumahku","nikah":1,"blok":"pagi"},"s":"Pagi! Jangan gerak! …Klik. Foto bangun tidur nomor dua ratus tiga. Koleksi pribadi. Nggak dijual."},{"c":{"nikah":1},"s":"Rubrik 'Kota Kecil' bulan ini fotonya kamu lagi ngobatin Dimas. Kata redaksi, itu foto terbaik tahun ini. Hehe."},{"c":{"renggang":1},"s":"Oh, hai! Aku lagi… motret. Banyak. Sibuk. Nanti aja, ya."},{"c":{"musim":"kemarau"},"s":"Kemarau, langitnya bersih. Fotoku tajam semua. Aku suka kemarau, kecuali bagian keringetnya."},{"c":{"at":"studio","rain":1},"s":"Hujan, nggak bisa keliling. Aku cuci foto di kamar gelap. Mau lihat? Jangan buka pintunya. Serius, jangan!"},{"c":{"stres":60},"s":"Diem bentar. Aku foto kamu. …Nah, lihat. Mukamu capek banget. Istirahat, ya. Biar foto berikutnya senyum."},{"c":{"event":"K55"},"s":"Pameran Foto Warga! Talinya udah aku pasang keliling alun-alun. Ada foto Dokter juga. Nggak boleh protes."}],
"wulan":[{"c":{"at":"puskes","t":0,"only":1},"s":"Selamat pagi, Dok. Saya Wulan, bidan. Kalau ada pasien anak atau ibu hamil, kita kerja sama, ya."},{"c":{"t":0,"only":1},"s":"Sudah makan? Saya tanya semua orang, kok. Jangan tersinggung. Kebiasaan kerja."},{"c":{"at":"puskes","t":20},"s":"Antrean imunisasi hari ini tiga puluh. Tangan saya pegel. Tapi anak-anaknya lucu. Yang nangis juga lucu, sih. Dikit."},{"c":{"at":"posyandu","t":20},"s":"Posyandu hari ini di Kampung Asri. Bayinya Mas Rudi naik dua ons! Saya hampir tepuk tangan. Hampir, lho."},{"c":{"t":40},"s":"dr. Galih belum makan dari pagi. Nasinya saya taruh di mejanya. Nanti saya cek. Kalau belum dimakan, awas."},{"c":{"at":"puskes","t":40},"s":"Tensi Mbah Darmi tinggi lagi. Katanya gara-gara Pak Bowo. Saya bingung, Dok, itu nulisnya di kartu gimana."},{"c":{"t":60,"jaga":1,"blok":"malam"},"s":"Ada ibu mau melahirkan, kira-kira jam tiga. Saya tidur sebentar, ya. Kalau saya merem sambil duduk, jangan diganggu."},{"c":{"t":60},"s":"Kadang saya pulang, buka sepatu, terus ketiduran di kursi. Bangun-bangun sepatu sebelah masih kepakai."},{"c":{"h":20},"s":"Dok, sudah makan? …Yang ini bukan pertanyaan kerja. Saya beneran pengin tahu."},{"c":{"h":50},"s":"Biasanya saya yang nyuruh orang istirahat. Kalau kamu yang nyuruh saya, rasanya aneh. Tapi ya… saya nurut."},{"c":{"h":70},"s":"Saya nggak pernah cerita soal capek ke siapa-siapa. Ke kamu, saya cerita. Ternyata enteng juga, ya."},{"c":{"pacaran":1},"s":"Bayi ke-131 lahir semalam. Saya tulis di buku. Di sebelahnya saya tambahin: 'Dia nungguin di luar.' Kamu."},{"c":{"at":"puskes","pacaran":1},"s":"Kata Galih saya senyum terus hari ini. Saya bilang saya sedang bersikap profesional. Dia nggak percaya."},{"c":{"at":"rumahku","nikah":1,"blok":"pagi"},"s":"Sarapan sudah. Bekal sudah. Jangan lupa minum air. Itu perintah. Dari istri sekaligus bidan."},{"c":{"nikah":1},"s":"Ibu dari Dusun Atas kirim sayur lagi. Katanya buat menantu. Buat kamu. Saya cuma kebagian sisanya."},{"c":{"renggang":1},"s":"Iya. Saya ngerti. Saya ada di Puskesmas kalau perlu. Jaga diri, ya."},{"c":{"musim":"hujan"},"s":"Musim hujan, ibu hamil susah datang, jalannya licin. Jadi saya yang datang ke mereka. Pakai sandal jepit."},{"c":{"rain":1},"s":"Hujan. Kalau mau ke Posyandu, saya pinjam jas hujan Mas Raka. Oranye. Saya jadi kayak jeruk."},{"c":{"stres":60},"s":"Duduk. Saya ukur tensi. …Seratus tiga puluh. Belum bahaya. Tapi kalau naik lagi, saya larang kamu kerja. Serius."},{"c":{"event":"K15"},"s":"Saya buka lapak imunisasi di Pameran. Anak yang berani dapat stiker gigi. Idenya Dimas, katanya."}],
"putri":[{"c":{"at":"warung","staf":0},"s":"Lagi bantuin Tante Ratna, Dok. Kalau klinik butuh resepsionis, kabarin, ya! Nama orang sekampung saya hafal, lho."},{"c":{"at":"klinik","staf":1,"buka":1},"s":"Siap, Dok! Antrean hari ini lima. Pak Yusuf udah duduk dari jam tujuh. Katanya biar dapet kursi deket kipas."},{"c":{"at":"klinik","staf":1,"buka":1},"s":"Bu Lastri bawa klepon lagi. Udah saya bagi rata di meja belakang. Saya ambil dua. Upah ngebagi, hehe."},{"c":{"staf":1,"t":40},"s":"Dok, Tante Ratna nanya kenapa klinik tutup jam empat. Saya bilang dokter juga manusia. Langsung diem. Berhasil!"},{"c":{"at":"klinik","staf":1,"t":60,"tutup":1},"s":"Kuliah online saya minggu ini soal manajemen antrean. Dosennya pasti belum pernah lihat antrean Kamis di sini."},{"c":{"staf":1,"stres":60},"s":"Dok, sisa antrean saya geser ke besok, ya. Saya bilang ke pasien Dokter lagi rapat. Rapat sama kasur."},{"c":{"staf":1,"rain":1},"s":"Hujan, ruang tunggu bau payung basah. Jendelanya saya buka dikit, ya, Dok. Jangan protes."}],
"yoga":[{"c":{"at":"adji","staf":0},"s":"Sekarang bantu-bantu Mas Adji. Spreadsheet-nya berantakan, tapi orangnya lucu. Jadi seimbang, lah."},{"c":{"at":"klinik","staf":1,"buka":1},"s":"Sudah saya catat. Tiga kontrol, dua pasien baru, satu rujukan Puskesmas. Kursi tunggu cukup. Aman."},{"c":{"at":"klinik","staf":1,"buka":1},"s":"Tagihan Pak Gunawan sudah saya cetak dua lembar. Satu buat dia, satu lagi buat dia tempel di bukunya."},{"c":{"staf":1,"t":40},"s":"Jadwal kontrol saya taruh di hari Rabu, Dok. Antreannya jadi rata. Grafiknya cakep. Mau lihat? Lihat, dong."},{"c":{"staf":1,"t":60},"s":"Kemarin ada pasien marah. Biasanya saya hitung sampai sepuluh dalam hati. Kali ini saya dengerin. Ternyata dia lapar."},{"c":{"staf":1,"stres":60},"s":"Jam sebelas sampai satu saya kosongkan. Di sistem saya tulis 'sterilisasi'. Sterilisasi Dokter, maksudnya."}],
"rina":[{"c":{"at":"puskes","staf":0},"s":"Sementara saya bantu di Puskesmas. Bu Wulan galak, tapi galaknya bener. Kayak saya."},{"c":{"at":"klinik","staf":1,"buka":1},"s":"Suction, bur, kapas, lampu. Siap. Dokter tinggal duduk. Nggak usah buru-buru, pasiennya nggak bakal kabur."},{"c":{"at":"klinik","staf":1,"buka":1},"s":"Fajar, sarung tangan itu dibuka dari pergelangan, bukan dari jari. Ulang. Maaf, Dok, saya ngajar sebentar."},{"c":{"staf":1,"t":40},"s":"Di Metrapura saya kerja sampai jam sepuluh malam. Di sini jam empat udah pulang. Badan saya masih bingung."},{"c":{"at":"klinik","staf":1,"t":60,"tutup":1},"s":"Dok, sekarang kalau capek Dokter bilang. Dulu nggak pernah. Itu kemajuan. Saya catat, ya."},{"c":{"staf":1,"stres":60},"s":"Cukup. Pasien berikutnya saya tunda sejam. Dokter makan. Saya nggak nanya, saya ngasih tahu."}],
"fajar":[{"c":{"staf":0},"s":"Bapak nyuruh saya ngelamar ke klinik. Saya mau, Dok. Tapi kalau nggak diterima nggak apa-apa. Beneran nggak apa-apa."},{"c":{"at":"klinik","staf":1,"buka":1},"s":"Alat sudah steril. Sudah saya cek. Saya cek lagi. Oke. Sudah. …Saya cek sekali lagi, ya, Dok."},{"c":{"at":"klinik","staf":1,"buka":1},"s":"Pasien anak tadi nangis, Dok. Saya taruh lidah buaya di baki. Bener, kan? Bener. Oke. Bener, kan?"},{"c":{"staf":1,"t":40},"s":"Bapak kemarin minum obatnya sendiri, nggak disuruh. Saya sampai kaget. Dokter ngomong apa sama Bapak?"},{"c":{"staf":1,"t":60},"s":"Kata dr. Galih, ngecek tiga kali itu bukan penyakit. Asal jangan empat. Saya lagi latihan tiga kali."},{"c":{"staf":1,"stres":60},"s":"Dok, Dokter kelihatan… capek. Eh, maaf. Mau saya bikinin teh? Airnya udah saya cek. Air biasa, kok."}],
"dewi":[{"c":{"at":"puskes","staf":0},"s":"Saya bantu Bu Wulan dulu. Kalau klinik butuh perawat, saya siap. Sterilisasi saya rapi, Dok."},{"c":{"at":"klinik","staf":1,"buka":1},"s":"Autoklaf sudah jalan, dua puluh menit. Saya tunggu di sini. Saya nggak tenang ninggal autoklaf sendirian."},{"c":{"at":"klinik","staf":1,"buka":1},"s":"Pasien tadi bilang dulu ditambal di pasar. Saya… ya. Sudah saya catat di rekam medis, Dok."},{"c":{"staf":1,"t":40},"s":"Bapak saya keliling. Di pasar. …Dokter mungkin pernah dengar. Saya belum mau bahas sekarang, boleh?"},{"c":{"staf":1,"t":60},"s":"Kemarin saya lihat Bapak di alun-alun. Saya hampir nyapa. Belum jadi. Mungkin minggu depan."},{"c":{"staf":1,"stres":60},"s":"Duduk dulu, Dok. Nampannya biar saya yang rapikan. Dokter tarik napas aja dulu."}],
"udin":[{"c":{"at":"kos","staf":0},"s":"Monggo, Dok. Kos saya sepi, kamar masih ada. Kalau Dokter punya staf dari jauh, suruh ke sini, nggih."},{"c":{"at":"klinik","staf":1,"buka":1},"s":"Lantainya masih basah. Lewat pinggir, Dok. Jejak sepatu Dokter saya sudah hafal, gampang dipel."},{"c":{"at":"klinik","staf":1,"tutup":1},"s":"Lagu kesukaan Bu Melati. Jangan bilang saya fals, nggih.","a":"(Pak Udin bersenandung keroncong sambil menyapu.)"},{"c":{"staf":1,"t":40},"s":"Dulu di SD saya ngejar anak yang nyoret tembok. Sekarang saya ngejar debu. Debu lebih nurut, Dok."},{"c":{"at":"kos","staf":1,"t":60,"blok":"malam"},"s":"Mbak Rina, Bu Hana, Mas Bima, Mas Yoga. Kos saya ramai lagi. Bu Melati pasti senang, nggih."},{"c":{"staf":1,"stres":60},"s":"Dok, saya sudah tua. Saya hafal muka orang yang kebanyakan kerja. Monggo pulang. Lantainya biar saya."}],
"siti":[{"c":{"at":"angkringan","staf":0},"s":"Lagi bantuin Mas Slamet cuci piring, Dok. Kalau klinik butuh tukang bersih-bersih, saya yang paling cepet!"},{"c":{"at":"klinik","staf":1,"buka":1},"s":"Beres, Dok! Kaca udah kinclong. Tadi Pak Yusuf sampai ngaca sambil benerin peci. Hehe, jadi ganteng dia."},{"c":{"at":"klinik","staf":1,"buka":1},"s":"Siapa yang naruh gelas kopi di atas autoklaf?! Mas Bima, ya? Pasti Mas Bima. Hayo ngaku!"},{"c":{"staf":1,"t":40},"s":"Kartu pasien ketinggalan lagi di kursi. Udah saya kasih Putri. Orang sini hobinya lupa barang. Untung ada saya."},{"c":{"staf":1,"t":60},"s":"Anak sulung saya mau masuk SMA, Dok. Saya nabung dari gaji sini. Makasih, ya, Dok. Beneran."},{"c":{"staf":1,"stres":60},"s":"Dokter pulang! Kliniknya saya kunci. Jangan balik lagi. Ini perintah petugas kebersihan. Beres!"}],
"hana":[{"c":{"at":"perpus","staf":0},"s":"Saya baca-baca dulu sambil nunggu. Di pulau dulu perpustakaannya cuma satu rak. Ini sih surga."},{"c":{"at":"klinik","staf":1,"buka":1},"s":"Kursi dua siap! Scaling tiga, tambal dua. Saya seneng, lho. Karang lepas itu rasanya kayak ngelap kaca berembun."},{"c":{"at":"klinik","staf":1,"buka":1},"s":"Pasien tadi nanya saya asli mana. Saya bilang Tanjung Arum. Katanya 'Pantes, logatnya kayak ikan.' Maksudnya apa, coba?"},{"c":{"staf":1,"t":40},"s":"Mbah Darmi cerita soal banjir dulu. Saya cerita soal kapal yang nggak dateng. Terus kami diem lama. Diemnya enak."},{"c":{"staf":1,"t":60},"s":"Saya pasang peta pulau di dinding ruang periksa dua. Kalau pasien takut, saya ceritain pulaunya. Ampuh, lho."},{"c":{"staf":1,"stres":60},"s":"Pasien Dokter yang ringan saya ambil, ya. Saya suka scaling, kok. Dokter istirahat. Nggak usah sungkan."}],
"bima":[{"c":{"at":"kedai","staf":0},"s":"Kopi di sini lumayan. Untuk ukuran kota kecil. …Oke, enak. Jangan bilang Nadia saya bilang enak."},{"c":{"at":"klinik","staf":1,"t":0,"buka":1},"s":"Pasien hari ini dua belas? Di Metrapura saya dua puluh. Tapi oke. Kita lihat siapa yang lebih rapi."},{"c":{"at":"klinik","staf":1,"t":40,"buka":1},"s":"Pasien tadi cerita soal cucunya lima belas menit. Dulu pasti saya potong. Sekarang saya dengerin. Aneh, ya."},{"c":{"staf":1,"t":40},"s":"Coach Doni ngalahin saya voli lima belas kosong. Ego saya hancur lebur. Terus saya ketawa. Udah lama nggak gitu."},{"c":{"at":"klinik","staf":1,"t":60,"tutup":1},"s":"Minggu ini saya nggak ngitung jumlah pasien. Tadinya iseng doang. Ternyata lega juga."},{"c":{"staf":1,"stres":60},"s":"Kamu dulu juga kayak gini di klinik Surya. Terus tumbang. Saya lihat sendiri. Kali ini saya yang ambil alih."}],
"hasan":[{"c":{"tunggu":1},"s":"Masih lama, Dok? Sapi saya nunggu di pasar. Sapi nggak bisa disuruh antre. Saya juga nggak bisa! Cepet, ya."},{"c":{"at":"losmen","jenguk":1},"s":"Kasurnya keras. Kayak kasur saya. Enak. Besok jam delapan, ya. Jangan telat. Eh, saya yang nggak boleh telat."},{"c":{"at":"alun","t":40,"blok":"pagi"},"s":"Tensi saya seratus empat puluh, Dok! Turun! Istri saya sampai bikin syukuran kecil. Nasi kuning, lho!"},{"c":{"kontrol":1},"s":"Obatnya saya minum. Tiap hari. Fajar yang ngingetin. Anak itu kayak alarm, Dok. Nggak bisa dimatiin."}],
"yati":[{"c":{"tunggu":1},"s":"Bu Bidan bilang boleh ke sini, Dok. Beneran nggak apa-apa ke bayinya, kan? Maaf, saya nanya lagi."},{"c":{"at":"losmen","jenguk":1},"s":"Mas Joko jemput besok pagi. Saya nggak bisa tidur. Bukan karena gigi. Deg-degan aja, Dok."},{"c":{"t":40},"s":"Kemarin bayinya nendang pertama kali. Saya nangis. Mas Joko juga. Mertua belum tahu. Sebentar lagi, ya."},{"c":{"kontrol":1},"s":"Gigi saya udah nggak ngilu. Saya bisa makan lagi. Bayinya juga ikut makan, katanya. Lewat saya."}],
"dina":[{"c":{"tunggu":1},"s":"Boleh aku rekam ruang tunggunya? Buat konten. Vibes klinik kampungnya literally cute banget."},{"c":{"t":40},"s":"Video senyum asliku udah ditonton sepuluh ribu orang. Komennya baik semua. Satu julid. Udah aku hapus."},{"c":{"at":"roti","t":40},"s":"Lagi bantu Tari motret roti. Tari kaku banget di depan kamera. Kayak roti tawar. Literally."},{"c":{"kontrol":1},"s":"Karangnya nggak balik lagi. Sekarang aku sikat gigi pakai timer. Dua menit. Ternyata aesthetic juga."}],
"yusuf":[{"c":{"tunggu":1},"s":"Alhamdulillah, dapat kursi dekat kipas. Silakan yang lain duluan, Nak. Saya bisa menunggu."},{"c":{"at":"losmen","jenguk":1},"s":"Fikri titip kertas obat. Ini. Tulisannya rapi, ya? Dia mau jadi apoteker, Nak. Seperti Tika."},{"c":{"at":"alun","t":40,"blok":"pagi"},"s":"Nenek Sumi sudah mau ke klinik? Alhamdulillah. Saya bujuk dia tiga bulan. Saya juga sabar, Nak."},{"c":{"kontrol":1},"s":"Darahnya cepat berhenti, Nak. Alhamdulillah. Saya ceritakan ke jamaah. Mereka mau datang semua."}],
"kiki":[{"c":{"tunggu":1},"s":"…","a":"(Kiki menatap kursi dental tanpa berkedip.)"},{"c":{"at":"sd","t":20},"s":"Dimas bilang Dokter nggak nyuntik. Bener?"},{"c":{"t":40},"s":"Gigiku di kotak. Kenang-kenangan hiu. Mau lihat? Jangan dipegang."},{"c":{"kontrol":1},"s":"Gigi baruku tumbuh lurus. Nggak dobel lagi. Aku masih hiu. Hiu yang rapi."}],
"rudi":[{"c":{"tunggu":1},"s":"Santai, Dok. Cuma bengkak dikit. …Eh, ini antreannya masih berapa? Kok lama, ya. Aduh."},{"c":{"at":"puskes","jenguk":1},"s":"Bu Bidan galak. Saya disuruh tidur terus. Pak Arya nelepon nanyain saya. Ternyata bos saya baik, Dok."},{"c":{"t":40},"s":"Anak saya udah bisa senyum, Dok. Giginya belum ada. Nanti kalau udah tumbuh, ke sini. Bukan ke pasar."},{"c":{"kontrol":1},"s":"Pipi saya udah kempes. Kata istri saya ganteng lagi. 'Lagi' itu artinya dulu pernah, kan, Dok?"}],
"lastri":[{"c":{"tunggu":1},"s":"Ini klepon buat Mbak resepsionis. Eh, buat Dokter juga. Ambil, ambil. Yang ijo lebih enak, lho."},{"c":{"at":"alun","t":40,"blok":"pagi"},"s":"Kamis, Dok! Kue saya laris. Yang rendah gula juga laku. Saya nggak nyangka. Kak Tari juga nggak."},{"c":{"t":40},"s":"Gula darah saya sekarang 'lumayan' beneran, Dok. Bukan lumayan yang dulu. dr. Galih sampai senyum."},{"c":{"kontrol":1},"s":"Gusi saya nggak berdarah lagi. Saya bisa makan nagasari sendiri. Satu. Satu aja, Dok. Sumpah."}],
"marno":[{"c":{"tunggu":1},"s":"Saya bawa warga saya tiga orang lagi, Dok. Program desa. Saya? Oh, saya cuma mengantar. Cuma mengantar."},{"c":{"t":40},"s":"Pilkades tinggal enam bulan. Laras sudah motret saya. Senyum saya sekarang layak baliho. Berkat Dokter."},{"c":{"at":"balai","t":40},"s":"Habis rapat sama Pak Harjo. Argumennya selalu menang. Tapi warga saya lebih banyak. Jadi ya… seri."},{"c":{"kontrol":1},"s":"Jarumnya kecil, kan, Dok? Kecil. Oke. Saya kepala desa. Saya berani. Kecil, kan?"}],
"tika":[{"c":{"tunggu":1},"s":"Saya izin ke Kak Nadia sebentar. Jam empat harus balik ke kedai. Masih keburu, kan, Dok?"},{"c":{"at":"kedai","t":20},"s":"Pesan apa, Dok? Kopi susu? Hari ini saya yang bikin. Kak Nadia lagi ke kebun. Rahasia, katanya."},{"c":{"at":"perpus","t":40},"s":"Lagi belajar kimia. Susah. Mbak Sekar kasih saya meja dekat jendela. Katanya biar otaknya kena angin."},{"c":{"kontrol":1},"s":"Gigi saya masih ada, Dok. Saya bisa senyum di foto ujian. Bapak bangga. Saya juga."}],
"gunawan":[{"c":{"tunggu":1},"s":"Saya catat jam saya datang. Delapan lewat dua. Nanti saya catat juga jam saya dipanggil. Biar adil."},{"c":{"t":40},"s":"Halaman Dokter di buku saya sudah saya sobek. Halaman dokter lain masih ada. Dokter yang pertama."},{"c":{"at":"alun","t":40,"blok":"pagi"},"s":"Mas Arya beli semen di toko saya. Saya kasih diskon. Dia nggak minta. Saya sendiri juga kaget."},{"c":{"kontrol":1},"s":"Tambalan ini masih bagus. Tiap pagi saya cek pakai lidah. Nggak goyang. Sudah saya catat."}],
"sumi":[{"c":{"tunggu":1},"s":"Ojo, Nak, ojo cepet-cepet. Nenek duduk dulu. Nenek lihat kursinya dulu. Kursinya galak, ndak?"},{"c":{"at":"puskes","jenguk":1},"s":"Darmi tadi ke sini. Bawa jamu. Pahit. Katanya buat Nenek. Padahal buat dia sendiri, biar dia tenang."},{"c":{"at":"alun","t":40,"blok":"pagi"},"s":"Mata Nenek masih terang, Nak! Masih bisa lihat cicit. Cabut gigi ndak bikin buta. Wis Nenek ceritain semua orang."},{"c":{"kontrol":1},"s":"Pardi nikah bulan depan. Nenek bisa makan sate. Sedikit. Yang empuk. Pakai gigi yang tersisa."}],
"andre":[{"c":{"tunggu":1},"s":"Siap, Coach! Eh, Dok! Maaf, maaf. Tadi habis latihan. Masih keringetan."},{"c":{"at":"voli","t":20},"s":"Dok! Lihat smash saya! …Tadi merem. Yang tadi nggak dihitung. Ulang!"},{"c":{"at":"voli","t":40},"s":"Sekarang pakai pelindung mulut. Coach maksa semua pakai. Rasanya kayak ngemut sandal. Tapi aman."},{"c":{"kontrol":1},"s":"Gigi depan saya udah nggak nyetrum. Saya bisa minum es lagi. Jangan bilang Coach saya minum es, ya."}],
"hendra":[{"c":{"at":"bahari","t":0,"only":1},"s":"Selamat datang di Bahari Medika! Cari apa, Dok? Alat apa saja ada. Kalau nggak ada, saya pesankan. Haiya, duduk dulu!"},{"c":{"at":"bahari","t":20},"s":"Ultrasonik ini garansi setahun. Kalau rusak, bawa ke sini. Kalau nggak rusak, bawa kopi Rimbasari ke sini. Harga teman!"},{"c":{"at":"bahari","t":40},"s":"Lina! Ini Dokter yang di Rimbasari, ponakannya Om Darto! Bikinin teh. Yang enak, bukan yang buat sales."},{"c":{"t":60},"s":"Om Darto dulu duduk di kursi itu tiap bulan. Kursinya belum saya ganti. Silakan duduk, Dok."},{"c":{"rain":1},"s":"Hujan di pelabuhan, kapal nggak bongkar. Barang telat dua hari. Haiya. Saya kasih diskon telat. Sedikit. Rugi, rugi."}],
"melinda":[{"c":{"at":"metra","t":0,"only":1},"s":"Selamat siang. Metra Dental Supply. Sebelum bahas alat, berapa staf Anda, dan jam berapa mereka pulang?"},{"c":{"at":"metra","t":20},"s":"Panoramik ini bukan mainan, Dok. Pastikan perawat Anda dilatih dulu. Modulnya bisa saya kirim."},{"c":{"t":40},"s":"Saya dengar Anda kirim staf ikut pelatihan. Good. Itu jarang di kota kecil. Di kota besar juga jarang."},{"c":{"at":"metra","t":60},"s":"Kopi dari Rimbasari? Hm. Saya taruh di pantry staf. Orang-orang saya juga berhak minum yang enak."},{"c":{"stres":60},"s":"Anda mirip perawat saya dulu waktu jaga tiga shift. Duduk. Saya ambilkan air."}],
"surya":[{"c":{"at":"losmen","Bab4":1,"blok":"malam"},"s":"Losmennya bersih. Mengejutkan. Kota ini… tenang sekali, ya. Saya justru tidak bisa tidur kalau terlalu tenang."},{"c":{"at":"alun","Bab4":1},"s":"Tidak ada papan peringkat. Tidak ada target. Lalu bagaimana kita tahu kamu sedang berhasil, {nama}?"},{"c":{"at":"bukit","Bab4":1},"s":"Saya lupa kapan terakhir lihat bintang. Di Metrapura langitnya oranye. Saya kira itu normal."},{"c":{"Epilog":1},"s":"Suratmu sudah saya terima. Saya baca dua kali. Saya juga ambil cuti seminggu. Yang pertama dalam dua puluh tahun."}],
"joni":[{"c":{"at":"alun","t":0,"only":1,"pasar":1},"s":"Murah, Bu, murah! Tambal tiga puluh ribu! Gigi palsu bisa nyicil! Lho, Dokter? Oh. Lewat aja, Dok, lewat."},{"c":{"at":"alun","t":20,"pasar":1},"s":"Dokter mau apa? Saya cuma jualan. Orang butuh, saya ada. Dokter ke mana sepuluh tahun lalu?"},{"c":{"x":1},"s":"Saya sudah nggak nambal, Dok. Cuma gigi palsu. Kertasnya resmi. Dewi yang urus. Anak saya."},{"c":{"at":"klinik","x":1},"s":"Ini gigi palsu Pak Wiryo yang baru. Pas, katanya. Nggak sariawan lagi. Saya… seneng dengernya."},{"c":{"x":1},"s":"…Saya pindah ke pasar lain, Dok. Nggak usah khawatir. Sekarang saya cuma bikin gigi palsu. Sendirian."}]};
const NPC_SCENES = {"harjo":[{"t":20,"c":{},"p":[{"act":"(Klinik baru saja sepi. Pak Harjo berdiri di depan pintu, membetulkan pecinya.)"},{"s":"Maaf, Dok, saya nggak mau ganggu. Cuma mau tanya-tanya sedikit, nggih."},{"s":"Gigi bawah saya ini kok goyang, ya. Kalau sudah tua memang begitu, atau masih bisa diapa-apakan?"},{"act":"(Kamu menjelaskan soal karang gigi dan gusi. Dia mengangguk pelan, seperti sedang mencatat dalam hati.)"},{"s":"Kalau begitu, kapan-kapan saya daftar. Pagi-pagi saja, biar nggak ketahuan Bu Ratna."}]},{"t":40,"c":{"at":"balai"},"p":[{"act":"(Di meja Pak Harjo ada selembar kuitansi. Kamu sempat membaca tulisannya: Pajak Bumi, Ruko Sumber Rejeki.)"},{"act":"(Dia buru-buru melipatnya dan memasukkannya ke laci.)"},{"s":"Itu... anggap saja Dokter nggak lihat, nggih."},{"s":"Setahun ruko itu kosong. Kalau pajaknya nunggak, ya dilelang. Saya nggak tega."},{"s":"Saya cuma mikir, siapa tahu ahli warisnya datang. Eh, yang datang malah dokter gigi. Gusti Allah itu lucu, Dok."}],
"ev":1},{"t":60,"c":{},"p":[{"s":"Dok, saya mau minta tolong. Ini agak berat."},{"s":"Warga masih banyak yang ke lapak Pak Joni. Saya nggak bisa melarang. Saya lurah, bukan polisi."},{"s":"Tapi kalau yang bicara Dokter, di depan warga, mungkin mereka mau dengar. Nanti saya kumpulkan di Balai, nggih?"}]},{"t":80,"c":{"at":"alun","blok":"sore"},"p":[{"act":"(Selesai keliling, Pak Harjo mengajakmu naik ke Bukit Bintang. Lampu-lampu kota mulai menyala satu per satu.)"},{"s":"Dua tahun lagi saya pensiun, Dok. Dulu saya bingung, siapa yang mau meneruskan."},{"s":"Dulu saya kira yang perlu diwariskan itu jabatan. Ternyata orang yang mau tinggal."},{"s":"Terima kasih sudah tinggal, nggih. Itu saja. Ayo turun, nanti istri saya telepon."}],
"ev":1}],
"ratna":[{"t":20,"c":{},"p":[{"s":"Dok, Dok! Sini dulu. Mulai sekarang Ibu kasih kabar yang penting-penting aja, ya."},{"s":"Siapa yang lagi sakit gigi, siapa lagi di mana. Biar Dokter nggak nyari-nyari."},{"s":"Gratis, lho. Eh, nggak gratis ding. Belanja dikit."}]},{"t":40,"c":{},"p":[{"s":"Dok, kemarin ada yang ngomong klinik Dokter mahal. Ibu langsung jawab!"},{"s":"Ibu bilang, mahal mana sama gigi copot? Orangnya diem. Hehe. Pokoknya kalau ada yang ngomong jelek, lapor Ibu."}]},{"t":60,"c":{"at":"warung"},"p":[{"act":"(Bu Ratna duduk di balik etalase, memegang sebuah surat. Kertasnya terbalik.)"},{"act":"(Dia melihatmu memperhatikan, lalu pelan-pelan meletakkan suratnya.)"},{"s":"Aduh. Ketahuan, ya."},{"s":"Ibu nggak bisa baca, Dok. Dari dulu. Kelas tiga udah berhenti sekolah, jagain adik-adik."},{"s":"Surat Bagus selalu Ibu suruh Tari yang baca. Bilangnya kacamata ketinggalan. Padahal Ibu nggak punya kacamata."},{"s":"Jangan bilang siapa-siapa, ya. Yang ini beneran, Dok."}],
"ev":1},{"t":80,"c":{},"p":[{"s":"Dok, Bagus kirim surat lagi. Mau... bacain buat Ibu?"},{"act":"(Kamu membacakannya pelan-pelan. Bagus minta dikirimi sambal. Bu Ratna tertawa sambil mengusap mata.)"},{"s":"Eh, Dok. Kata Mbak Sekar, di perpustakaan ada buku buat belajar baca. Kalau Ibu ke sana, Dokter mau nemenin?"}]}],
"darmi":[{"t":20,"c":{},"p":[{"s":"Hm. Kowe meneh."},{"act":"(Mbah Darmi menyodorkan selembar daun hijau mengilap.)"},{"s":"Iki opo?"},{"act":"(Kamu menjawab: daun sirih, buat kumur dan gusi berdarah.)"},{"s":"Hm."},{"act":"(Dia mendengus. Kedengarannya puas.)"},{"s":"Besok tak tanya yang lain."}]},{"t":40,"c":{},"p":[{"s":"Wis. Mulai sekarang harga bibit sama kayak orang sini."},{"s":"Ojo seneng dulu. Kalau bibitku mati di tanganmu, harganya naik lagi."}]},{"t":60,"c":{"at":"jamu","blok":"sore"},"p":[{"act":"(Sore itu langit mendung. Mbah Darmi berhenti menumbuk, lalu menyuruhmu duduk.)"},{"s":"Bojoku, Mbah Karto. Empat puluh tahun lalu giginya bengkak sampai pipi."},{"s":"Semua jamu wis tak coba. Jalan ke Tanjung Arum putus, banjir. Tiga hari. Terus..."},{"act":"(Dia membuka buku catatan lusuh dan menunjukkan halaman terakhir. Tulisannya gemetar.)"},{"act":"(\"Gigi bengkak: jamu ora cukup. Harus ke dokter.\")"},{"s":"Aku nulis iki sehari setelah dia dikubur. Makanya aku sinis karo dokter kota, Le. Bukan sama kowe. Sama diriku."}],
"ev":1},{"t":80,"c":{},"p":[{"s":"Gigiku sing iki wis lama tinggal akar. Ora sakit, tapi ngganjel."},{"s":"Besok-besok aku mampir klinikmu. Ojo bilang Ratna."},{"s":"Coba dulu ada kowe, Le."}]}],
"dimas":[{"t":20,"c":{},"p":[{"s":"Dok, aku mau duduk di kursi yang bisa naik turun itu. Tapi cuma duduk, ya!"},{"s":"Nggak pakai buka mulut. Nggak pakai lampu. Beneran cuma duduk. Janji?"}]},{"t":40,"c":{},"p":[{"s":"Dok, kaca kecil itu namanya apa? Kaca mulut? Nggak keren."},{"s":"Aku kasih nama Robo-Kaca. Yang buat nyedot air itu Robo-Sedot. Kalau pakai Robo-Kaca aja, aku mau diperiksa."}]},{"t":60,"c":{"at":"endang"},"p":[{"act":"(Dimas menarikmu ke pojok, jauh dari mesin jahit ibunya.)"},{"s":"Dok... gigi belakangku sakit tiap malam. Udah lama."},{"act":"(Dia mengeluarkan segenggam bungkus permen dari saku.)"},{"s":"Ini dari laci kaus kaki. Aku nggak bilang Ibu soalnya Ibu pernah nangis gara-gara uang sewa."},{"s":"Jangan bilang Ibu, ya. Eh. Bilang aja, deh. Tapi pelan-pelan bilangnya."}],
"ev":1},{"t":80,"c":{},"p":[{"s":"Dok, Dok! Aku gambar Dokter! Ini Dokter Robot Gigi. Tangannya bisa jadi bor, tapi bornya nggak sakit."},{"s":"Nanti aku tempel di klinik, ya. Terus aku nggak jadi insinyur robot. Aku mau jadi dokter gigi aja. Yang robot."}]}],
"endang":[{"t":20,"c":{},"p":[{"s":"Maaf lho, Dok, ganggu. Dimas itu... kalau Dokter nggak keberatan, Ibu ajak lihat-lihat ke klinik."},{"s":"Lihat-lihat saja, nggih. Nggak diapa-apakan. Biar dia tahu dokter gigi itu nggak semuanya kayak dulu."}]},{"t":40,"c":{},"p":[{"s":"Dok, jas Dokter itu sudah tipis di siku. Ibu jahitkan seragam klinik, nggih?"},{"s":"Bayarnya nanti dipotong ongkos periksa Dimas."},{"s":"Nggak usah sungkan. Ini barter, bukan minta-minta."}]},{"t":60,"c":{"at":"endang","jam":21},"p":[{"act":"(Sudah jam sepuluh malam. Mesin jahit Bu Endang masih berbunyi. Tangan kirinya memegangi pipi.)"},{"s":"Eh, Dok. Maaf, Ibu kira siapa. Nggak apa-apa, cuma ngilu dikit."},{"act":"(Kamu duduk dan menunggu. Lama dia diam, lalu menghela napas.)"},{"s":"Geraham Ibu kayaknya retak, Dok. Kalau tidur Ibu suka gemeletuk. Tidurnya juga cuma empat jam."},{"s":"Ibu diam soalnya uangnya buat Dimas. Maaf lho, malah curhat."}],
"ev":1},{"t":80,"c":{},"p":[{"s":"Dok, kiriman Mas Wahyu telat terus itu ternyata tangannya cedera. Dia malu bilang."},{"s":"Ibu sempat marah. Sekarang Ibu cuma pengin dia pulang."},{"s":"Makasih sudah bantu Ibu sama Dimas. Ini bukan sedekah lho, Dok. Ini namanya tetangga."}]}],
"bowo":[{"t":20,"c":{},"p":[{"s":"Halah. Iya, iya. Dokter lumayan."},{"s":"Lumayan. Bukan bagus. Wis lah, saya mau ke kebun."}]},{"t":40,"c":{},"p":[{"act":"(Kamu bertanya soal sekarung kecil kopi di depan pintu klinik tadi pagi. Di karungnya tertulis spidol: KEBUN BOWO.)"},{"s":"Halah. Karung apa? Nggak tahu. Kopi nyasar, mungkin."},{"act":"(Dia langsung sibuk membetulkan capingnya.)"},{"s":"Kalau nyasar ya diminum. Jangan dikasih susu."}]},{"t":60,"c":{"at":"kopi"},"p":[{"act":"(Angin lereng menerbangkan caping Pak Bowo. Selembar foto jatuh dari lipatannya: anak perempuan berseragam SD.)"},{"act":"(Dia memungutnya pelan-pelan dan lama tidak bicara.)"},{"s":"Ningsih. Anak saya. Sepuluh tahun nggak telepon."},{"s":"Dulu saya larang dia kuliah. Saya bilang perempuan buat apa sekolah tinggi. Dia pergi malam-malam."},{"s":"Saya salah, Dok. Tapi saya nggak tahu cara bilangnya."}],
"ev":1},{"t":80,"c":{},"p":[{"s":"Dok, ikut saya ke Kantor Pos, ya. Saya mau kirim surat ke Ningsih."},{"s":"Tulisan saya jelek. Dokter yang nulis, saya yang tanda tangan. Halah, jangan senyum-senyum."}]}],
"sinta":[{"t":20,"c":{},"p":[{"s":"Nah, Dok, saya mau mengundang secara resmi. Nanti ada Pameran Gigi Sehat di sekolah."},{"s":"Satu, Dokter datang. Dua, bawa gigi-gigian. Tiga, jangan pakai jas putih dulu. Ya, Dok?"}]},{"t":40,"c":{},"p":[{"s":"Dok, saya sudah bilang ke anak-anak kelas tiga. Nanti saya bawa mereka periksa ramai-ramai."},{"s":"Kalau ramai-ramai, yang penakut jadi berani. Kecuali Dimas. Dimas tetap sembunyi di belakang Kiki."}]},{"t":60,"c":{"at":"perpus"},"p":[{"act":"(Bu Sinta menutup bukunya, lalu mengeluarkan amplop cokelat dari tas.)"},{"s":"Ini surat mutasi ke Tanjung Arum, Dok. Sudah tiga bulan di laci."},{"s":"Ibu saya di sana sendirian. Makin sering sakit. Tapi murid-murid di sini..."},{"s":"Kalau Dokter, pergi atau tinggal?"},{"act":"(Kamu tidak langsung menjawab. Dia tersenyum kecil.)"},{"s":"Nggak apa-apa, Dok. Saya juga belum tahu."}],
"ev":1},{"t":80,"c":{},"p":[{"s":"Dok, Dokter orang pertama yang saya kasih tahu. Saya tinggal."},{"s":"Ibu saya jemput ke sini. Biar tinggal sama saya."},{"s":"Saya kira betah itu soal kotanya. Ternyata soal orang-orangnya, ya."}]}],
"slamet":[{"t":20,"c":{},"p":[{"s":"Wedang jahe, gorengan dua, kan? Saya sudah hafal, Dok."},{"s":"Tidurnya cukup, Dok? Muka Dokter itu kayak bus jam tiga pagi. Jalan, tapi lampunya redup."}]},{"t":40,"c":{},"p":[{"s":"Dok, saya mau ngomong jujur, ya. Monggo didengar, nggak usah dijawab."},{"s":"Kerja itu kayak nyetir malam. Kalau ngantuk, minggir. Jangan nunggu nabrak."}]},{"t":60,"c":{"at":"angkringan"},"p":[{"act":"(Angkringan sepi. Pak Slamet duduk di sebelahmu dan menuang teh untuk dirinya sendiri.)"},{"s":"Tujuh tahun lalu, Dok. Bus saya bawa dari Metrapura, jam dua pagi. Dada saya kayak dihimpit."},{"s":"Bus hampir masuk jurang. Untung kenek saya narik rem tangan."},{"s":"Sejak itu saya minum obat pengencer darah tiap hari. Cuma Yuni yang tahu. Sekarang Dokter."},{"s":"Kalau suatu hari saya cabut gigi, Dokter jangan lupa, ya. Saya sendiri kadang lupa bilang."}],
"ev":1},{"t":80,"c":{"at":"angkringan"},"p":[{"act":"(Belum jam sembilan, Pak Slamet sudah menurunkan terpal angkringan.)"},{"s":"Tutup dulu. Ayo, Dok, ikut."},{"act":"(Kalian duduk di Bukit Bintang. Lampu kota kelihatan kecil sekali dari atas.)"},{"s":"Saya dulu kayak Dokter. Gas terus. Ujung-ujungnya badan yang ngerem sendiri."},{"s":"Capek itu boleh, Dok. Asal jangan nunggu badan yang ngerem."}],
"ev":1}],
"tari":[{"t":20,"c":{},"p":[{"s":"Eh, Dok. Dokter nggak marah kan saya jualan gula? Hehe."},{"s":"Eh tapi serius, lho. Saya kepikiran. Masa dokter gigi beli roti di sini tiap hari. Kayak polisi beli di toko maling."}]},{"t":40,"c":{},"p":[{"s":"Dok... sebenarnya gigi saya sering ngilu. Kalau minum es, langsung nyut."},{"s":"Jangan ketawa, ya. Tukang roti giginya bolong. Nanti kalau toko sepi, saya mampir klinik, deh."}]},{"t":60,"c":{"at":"roti"},"p":[{"act":"(Kak Tari mengajakmu ke belakang toko dan membuka lemari. Ada seragam koki putih, masih rapi tergantung.)"},{"s":"Lima tahun saya di dapur hotel Metrapura. Bikin croissant tiga ratus biji tiap pagi."},{"s":"Terus Ayah stroke. Saya pulang. Seragamnya saya bawa, nggak tahu buat apa."},{"s":"Hotelnya masih kirim email, lho. Saya masih bales. Eh tapi saya nggak akan pergi, kok."},{"s":"Itu cuma biar saya ngerasa masih punya pilihan. Aneh, ya?"}],
"ev":1},{"t":80,"c":{},"p":[{"s":"Dok, Dok! Saya mau bikin Roti Senyum. Gulanya sedikit, tapi tetap enak. Dokter yang jadi tukang cicip."},{"s":"Nanti di Syukuran saya luncurin. Foto Dokter saya pasang di etalase. Nggak boleh nolak. Hehe."}]}],
"ilham":[{"t":20,"c":{},"p":[{"s":"Dok, lihat! Kartu pos dari Tanjung Arum. Ada lautnya."},{"s":"Saya koleksi dari kota-kota yang belum pernah saya datengin. Udah empat puluh tiga."},{"s":"Semua pintu di sini saya hafal. Laut aja yang belum pernah saya ketok."}]},{"t":40,"c":{},"p":[{"s":"Siap, Dok! Bocoran dikit: minggu ini kiriman dari Tanjung Arum lancar. Alat aman."},{"s":"Oh iya... ada surat lama juga. Nanti aja, ya. Belum waktunya."}]},{"t":60,"c":{"at":"pos"},"p":[{"act":"(Mas Ilham menarik laci paling bawah dan mengeluarkan amplop kekuningan. Cap posnya sudah lama.)"},{"s":"Dok, ini surat buat Dokter. Dari Om Darto. Dulu balik ke sini, alamatnya nggak dikenal."},{"s":"Saya simpan terus. Maaf baru sekarang. Saya bingung kapan waktu yang pas."},{"act":"(Kamu membukanya. Tulisannya miring, pakai tinta biru.)"},{"act":"(\"Dulu orang tuamu yang menolong toko Om waktu hampir bangkrut. Om baca kartumu: kamu mau jadi dokter gigi.\")"},{"act":"(\"Ruko ini cuma bisa jualan gula. Mungkin di tanganmu, ruko ini bisa ganti jualan senyum.\")"},{"s":"Surat itu mirip gigi, Dok. Makin lama ditunda, makin nyut-nyutan. Akhirnya sampai juga."}],
"ev":1},{"t":80,"c":{},"p":[{"s":"Dok, kalau Dokter ke Tanjung Arum lagi, saya boleh ikut sekali? Pas libur."},{"s":"Saya pengin lihat laut. Sekali aja. Habis itu saya bisa pamer ke adik-adik."}]}],
"wiryo":[{"t":20,"c":{},"p":[{"s":"Duduk, Nak. Kursi itu sudah setahun kosong."},{"s":"Nggak usah main. Temani saja. Orang tua itu kalau mainnya nggak ditonton, rasanya kayak ngajar kelas kosong."}]},{"t":40,"c":{},"p":[{"s":"Aduh, Nak. Sariawan lagi. Gigi palsu ini longgar, bikinan Joni."},{"act":"(Kamu memberi resep salep dan cara merawatnya, lalu menyarankan dia berhenti dulu memakai gigi palsu itu.)"},{"s":"Jadi selama ini salah gigi palsunya, bukan salah umur saya. Hehe. Nanti saya ke klinikmu."}]},{"t":60,"c":{"at":"alun"},"p":[{"s":"Skak, Darto. Kamu dari tadi diam saja. Biasanya kamu..."},{"act":"(Kakek Wiryo berhenti. Tangannya masih memegang kuda catur.)"},{"s":"Maaf, Nak. Saya panggil kamu Darto, ya?"},{"act":"(Dia mengeluarkan buku saku dan membuka halaman pertama.)"},{"act":"(\"Kalau keponakan Darto datang, ajak main catur. Dia pasti sendirian.\")"},{"s":"Saya mulai lupa banyak hal. Makanya saya catat. Tapi yang ini nggak pernah lupa."}],
"ev":1},{"t":80,"c":{},"p":[{"s":"Nak, papan ini punya Darto. Tiga puluh tahun kami main di sini."},{"s":"Bawa pulang, pajang di klinikmu atau di rumah. Biar dia ikut lihat kamu kerja."}]}],
"doni":[{"t":20,"c":{},"p":[{"s":"Dok! Tiap sore jam empat di lapangan. Ikut, ya? Yang kalah traktir es teh. Gas!"}]},{"t":40,"c":{},"p":[{"s":"Dok, saya titip Andre. Kemarin giginya kena bola lagi. Tolong anak saya. Eh, murid saya."},{"s":"Pokoknya kalau dia ke klinik, Dokter yang pegang. Saya percaya."}]},{"t":60,"c":{"at":"voli"},"p":[{"act":"(Semua sudah pulang. Coach Doni duduk di bangku, memijat lututnya, lama tidak bicara.)"},{"s":"Umur dua puluh empat ligamen saya putus, Dok. Sebulan sebelum seleksi nasional."},{"s":"Saya sempat di Metrapura. Malam-malam saya duduk di terminal, nggak tahu mau pulang atau ke mana."},{"s":"Terus saya pulang. Ngelatih anak-anak. Andre giginya patah gara-gara saya maksa latihan pas lapangan basah."},{"s":"Belum berani ngomong ke orang tuanya. Dokter jangan bilang dulu, ya. Saya sendiri yang ngomong."}],
"ev":1},{"t":80,"c":{},"p":[{"s":"Dok, Pesta Rakyat nanti ada turnamen. Jadi dokter tim saya, ya?"},{"act":"(Dia mengulurkan sebuah peluit merah.)"},{"s":"Peluit cadangan. Kalau ada anak yang ngeyel, tiup aja. Ayo!"}]}],
"hendra":[{"t":20,"c":{},"p":[{"s":"Dok, saya kasih tahu, ya. Barang yang bener-bener perlu itu ini, ini, sama ini. Sisanya cuma gaya."},{"s":"Saya jualan, tapi nggak mau Dokter rugi. Om Darto dulu juga saya kasih tahu begitu. Haiya, dia nggak pernah dengar."}]},{"t":40,"c":{},"p":[{"s":"Mulai sekarang harga teman, Dok. Lima persen. Rugi, rugi. Tapi teman."}]},{"t":60,"c":{"at":"bahari"},"p":[{"act":"(Koh Hendra mengajakmu ke belakang toko. Dia membuka buku kas tua bersampul kain.)"},{"s":"Ini buku kas papa saya. Lihat tulisan ini. Ini tangan Om Darto. Tiap bulan dia belanja, tiap bulan dia nyatat sendiri."},{"s":"Papa saya dulu janji sama Om Darto. Rimbasari jangan sampai kurang alat."},{"s":"Puskesmas di kota Dokter itu, alatnya saya yang titip. Atas nama papa. dr. Galih nggak tahu."},{"s":"Sekarang ada Dokter. Harga teman jadi sepuluh persen. Itu bukan diskon, Dok. Itu janji."}],
"ev":1}],
"rina":[{"t":60,"c":{},"p":[{"s":"Dok, ada yang mau saya ceritain. Dari dulu."},{"s":"Waktu Dokter pingsan di ruang sterilisasi Surya, yang telepon ambulans itu saya."},{"s":"Saya nggak pernah bilang. Nggak penting siapa yang telepon."},{"s":"Saya cuma mau lihat Dokter sehat. Itu aja. Makanya saya di sini."}],
"ev":1}],
"hana":[{"t":60,"c":{},"p":[{"act":"(drg. Hana mengajakmu ke Pondok Jamu. Mbah Darmi sedang menumbuk kunyit.)"},{"s":"Di pulau dulu, Dok, saya pernah punya pasien abses. Kapalnya nggak datang empat hari."},{"s":"Pasiennya selamat. Tapi tiap dengar suara kapal, saya masih deg-degan."},{"s":"Hm. Aku ngerti. Aku karo banjir.","who":"darmi"},{"s":"Menunggu itu sing paling abot, Nduk. Saiki kowe ora perlu nunggu kapal. Ana dokter cedhak.","who":"darmi"},{"act":"(drg. Hana tertawa kecil sambil menyeka mata. Sore itu mereka bertukar resep sampai gelap.)"}],
"ev":1}],
"bima":[{"t":60,"c":{"at":"voli"},"p":[{"act":"(drg. Bima baru kalah tiga set dari Coach Doni. Dia duduk di pinggir lapangan, napasnya masih ngos-ngosan.)"},{"s":"Kamu tahu nggak, setelah kamu pergi, saya jadi nomor satu di papan Surya."},{"s":"Hari pertama jadi nomor satu, saya nangis di parkiran. Nggak tahu kenapa."},{"s":"Saya kira saya mau ngalahin kamu. Ternyata saya mau berhenti, tapi nggak tahu caranya."},{"s":"Udah. Jangan dibahas lagi. Besok saya mau balas Coach Doni."}],
"ev":1}]};
const NPC_SIKAP = {"ratna":[{"t":20,"c":{},"l":["Eh, Dok, jangan bilang siapa-siapa. {sakit} tadi pegang-pegang pipi terus. Kayaknya giginya lagi nyut-nyutan.","Oh iya, Dok. {orang} hari ini lagi di {tempat}. Kalau Dokter nyari."]}],"slamet":[{"t":40,"c":{"stres":60},"l":["Kopi lagi? Nggak, Dok. Ini sudah gelas ketiga. Saya ganti wedang jahe aja, ya. Yang ini gratis."]}]};
const NPC_EVENTS = {"adji":[{"n":1,"title":"Struk Berantakan","at":"klinik","jam":17,"c":{},"place":"Klinik · sore, setelah tutup","ajak":"Dok, nanti sore aku mampir ke klinik, ya? Jam lima. Aku bawa kopi dua. Satu buat kamu. Yang satu juga buat kamu, sih.","p":[{"act":"(Adji datang bawa dua gelas kopi. Matanya langsung nyangkut di kardus struk di pojok.)"},{"act":"(Dia tahan sekitar tiga detik.)"},{"s":"Dok. Boleh aku rapikan? Ini bikin aku nggak bisa tidur. Serius."}],"ask":"Adji pengin ngerapiin struk klinik. Kamu jawab apa?","o":[{"v":15,"label":"\"Ajarin aku aja, biar aku bisa sendiri.\"","r":[{"act":"(Dia girang sampai kopinya hampir tumpah.)"},{"s":"Serius? Oke. Pelajaran satu: struk itu bukan sampah."}]},{"v":5,"label":"\"Wah, makasih. Tolong ya.\"","r":[{"act":"(Dia merapikan sambil bersenandung. Senang, tapi kelihatan sedikit kecewa.)"}]},{"v":-10,"label":"\"Nggak usah, aku bisa sendiri.\"","r":[{"s":"Oh. Iya, iya. Maaf, kebiasaan."},{"act":"(Dia pulang. Kopinya masih penuh.)"}]}]},
{"n":2,"title":"Polo Hitam Ketujuh","at":"kedai","jam":12,"c":{},"place":"Kedai Kopi Seduh · siang","ajak":"Dok, besok… eh, nanti siang makan bareng, yuk? Jam dua belas di Kedai. Aku yang traktir. Udah aku anggarkan.","p":[{"act":"(Lima menit sebelum janji, kopi Nadia tumpah ke polo hitam Adji. Polo ketujuh. Satu-satunya yang masih bersih.)"},{"act":"(Kamu menemukan dia lagi ngelap baju pakai tisu, panik.)"},{"s":"Jangan lihat! Eh, udah lihat. Ya udah. Ini noda kopi, bukan noda moral, ya."}],"ask":"Polonya kena kopi tepat sebelum makan siang. Kamu bilang apa?","o":[{"v":15,"label":"\"Pakai polo kotor juga nggak apa-apa. Aku ke sini mau ketemu kamu, bukan bajumu.\"","r":[{"act":"(Dia diam. Kupingnya merah.)"},{"s":"…Oke. Itu kalimat bagus. Aku curi, ya."}]},{"v":5,"label":"(Ketawa, lalu bantu ngelap.)","r":[{"s":"Aduh, malu-maluin."},{"act":"(Makan siangnya tetap jalan, dan seru.)"}]},{"v":-10,"label":"\"Kok bisa sih? Ceroboh banget.\"","r":[{"s":"Iya, emang."},{"act":"(Sepanjang makan siang dia nutupin noda itu pakai tangan.)"}]}]},
{"n":3,"title":"Lembur Akhir Bulan","at":"adji","jam":20,"c":{},"place":"Kantor Akuntan · malam, akhir bulan","ajak":"Dok, nanti malam aku lembur. Akhir bulan. Kalau kamu lewat jam delapan, mampir, ya? Aku butuh saksi aku masih hidup.","p":[{"act":"(Lampu kantor masih nyala. Adji dikelilingi map, rambutnya acak-acakan. Dia lagi ngobrol sama kalkulator.)"},{"act":"(Pas istirahat makan, kamu iseng nanya kenapa dia belum pernah pacaran. Gosip Bu Ratna.)"},{"s":"Hahaha. Oke. Waktu SMA aku bacain puisi lucu buat Rini, di depan sekelas. Dia bilang, 'Kamu kan temen, Dji.'"},{"s":"Satu kelas inget sampai sekarang. Hahaha. Lucu, kan?"},{"act":"(Tawanya agak kaku.)"}],"ask":"Adji cerita soal Rini sambil ketawa. Kamu jawab apa?","o":[{"v":15,"label":"\"Aku nggak bakal ketawa kalau kamu serius.\"","r":[{"act":"(Dia berhenti ketawa.)"},{"s":"…Itu yang pengin aku denger dari dulu, kayaknya."}]},{"v":5,"label":"\"Ya ampun, itu kan udah lama.\"","r":[{"s":"Iya, ya. Udah lama banget."},{"act":"(Dia lega, lalu ganti topik.)"}]},{"v":-10,"label":"(Ikut ketawa keras.) \"Puisi? Di depan kelas? Ya pantes!\"","r":[{"act":"(Dia tetap ketawa, tapi lebih cepat balik ke mapnya.)"}]}]},
{"n":4,"title":"\"Kamu Udah Makan?\"","at":"klinik","jam":12,"c":{"stres":60},"place":"Klinik · siang","ajak":"Dok, siang ini aku ke klinik, ya. Jam dua belas. Nggak usah nanya kenapa. Pokoknya siapin meja kosong.","p":[{"act":"(Adji datang bawa rantang. Resep katering ibunya.)"},{"act":"(Ada telur dadar yang dia coba bentuk kayak gigi. Gagal total. Bentuknya kayak awan.)"},{"s":"Udah berhari-hari mukamu makin capek. Aku nggak buta, lho. Jadi aku tanya sekali aja. Kamu udah makan?"}],"ask":"Adji nanya kamu udah makan. Kamu jawab apa?","o":[{"v":15,"label":"\"Belum. Dan jujur, aku capek banget.\"","r":[{"act":"(Dia duduk, buka rantang, dan biarin kamu ngomong sampai selesai.)"},{"s":"Makasih udah nggak bohong."}]},{"v":5,"label":"\"Udah kok, tadi.\"","r":[{"s":"Bohong. Itu telur gigi, aku bikinnya dua jam. Makan."},{"act":"(Dia tetap nyodorin sendok.)"}]},{"v":-10,"label":"\"Aku sibuk, nanti aja.\"","r":[{"act":"(Dia naruh rantang di meja.)"},{"s":"Oke. Dipanasin dulu, ya."},{"act":"(Dia pergi tanpa melawak.)"}]}]},
{"n":5,"title":"Neraca Hati","at":"lereng.bukit","jam":20,"c":{},"place":"Bukit Bintang · malam","ajak":"Dok. Nanti malam jam delapan, Bukit Bintang. Aku mau ngomong sesuatu. Udah aku latih. Seminggu. Jangan ketawa dulu.","p":[{"act":"(Adji udah latihan ngomong di depan cermin seminggu. Adiknya merekam dan nyebarin videonya ke grup keluarga.)"},{"act":"(Sampai di atas bukit, dia lupa semuanya. Akhirnya dia ngeluarin kertas. Bentuknya neraca.)"},{"act":"(Kolom Aset: hal-hal yang dia suka dari kamu. Kolom Kewajiban cuma satu baris: \"Bilang sekarang.\")"},{"s":"Saldo akhirnya… aku suka kamu. Ini nggak bercanda. Sumpah. Aku udah ngecek dua kali."}],"ask":"Adji nyodorin neraca hatinya. Kamu jawab apa?","o":[{"v":15,"label":"(Ambil pulpennya, lalu tulis neraca balasan.)","r":[{"act":"(Dia membacanya dua kali.)"},{"s":"Seimbang. Ya ampun. Seimbang."}]},{"v":5,"label":"\"Kamu serius, kan? …Iya. Aku mau.\"","r":[{"act":"(Dia menghela napas panjang, lalu ketawa sampai keluar air mata.)"}]},{"v":-10,"label":"\"Kamu bercanda lagi, ya?\"","r":[{"act":"(Dia melipat kertasnya pelan.)"},{"s":"Nggak. Tapi nggak apa-apa."}]}]}],"arya":[{"n":1,"title":"Cek Struktur Ruko","at":"klinik","jam":7,"c":{},"place":"Klinik · pagi, sebelum buka","ajak":"Besok pagi. Jam tujuh. Klinik. Ada retak di dinding samping. Aku cek.","p":[{"act":"(Arya datang bawa senter. Tanpa basa-basi dia ngetuk-ngetuk dinding.)"},{"s":"Ada retak di sini. Rambut. Lebar 0,3 mili. Boleh aku cek?"},{"act":"(Lima belas menit dia memeriksa. Nggak ngomong sepatah kata pun.)"}],"ask":"Arya selesai memeriksa dinding. Kamu bilang apa?","o":[{"v":15,"label":"\"Ceritain dong apa yang kamu lihat. Aku pengin ngerti.\"","r":[{"act":"(Dia menggambar penampang dinding di balik kalender klinik, lalu menjelaskannya pelan-pelan.)"}]},{"v":5,"label":"\"Makasih, ya. Aman, kan?\"","r":[{"s":"Aman."},{"act":"(Lalu dia pamit.)"}]},{"v":-10,"label":"\"Siapa yang nyuruh kamu masuk?\"","r":[{"s":"Maaf."},{"act":"(Dia meninggalkan catatan teknis di meja, lalu pergi.)"}]}]},
{"n":2,"title":"Jembatan Kali","at":"lereng.bukit","jam":17,"c":{},"place":"Bukit Bintang · sore","ajak":"Jam lima sore. Bukit Bintang. Ada yang mau aku tunjukin. Dari atas kelihatan jelas.","p":[{"act":"(Dari atas bukit Arya menunjuk jembatan Kampung Kali di bawah.)"},{"s":"Itu jembatan pertama yang aku rancang. Tiga bentang. Fondasinya dua belas meter."},{"act":"(Lama dia diam. Lalu dia cerita soal banjir waktu umurnya sembilan. Rumahnya hanyut.)"}],"ask":"Arya baru cerita soal banjir waktu kecil. Kamu bilang apa?","o":[{"v":15,"label":"\"Berarti semua yang kamu bangun itu janji buat kamu yang umur sembilan, ya.\"","r":[{"act":"(Dia menatapmu lama.)"},{"s":"…Iya. Belum pernah ada yang ngomong gitu."}]},{"v":5,"label":"\"Jembatannya bagus.\"","r":[{"s":"Makasih."},{"act":"(Dia senang, tapi nggak cerita lebih jauh.)"}]},{"v":-10,"label":"\"Banjirnya udah lama banget, kan?\"","r":[{"act":"(Dia menutup buku sketsanya.)"}]}]},
{"n":3,"title":"Lereng Saat Hujan","at":"lereng.proyek","jam":19,"c":{"hujan":1},"place":"Lereng Bukit · malam, hujan deras","ajak":"Malam ini aku di lereng. Pasang patok. Bibit Tanam Pohon bisa kebawa air. Kalau mau lihat, jam tujuh.","p":[{"act":"(Hujan deras. Arya sendirian memasang patok bambu dan jaring di lereng.)"},{"act":"(Telapak tangannya robek kena kawat. Dia tetap nggak mau pulang.)"},{"s":"Dua puluh patok lagi. Kalau berhenti sekarang, bibitnya turun ke bawah."}],"ask":"Tangan Arya berdarah, tapi dia nggak mau berhenti. Kamu ngapain?","o":[{"v":15,"label":"(Bersihin dan balut lukanya di tempat, lalu ikut ngangkat karung.)","r":[{"s":"Kamu kan dokter gigi."},{"s":"Dan kamu insinyur yang lupa kalau punya tangan.","who":"me"}]},{"v":5,"label":"(Bawain kopi dan payung.)","r":[{"s":"Makasih."},{"act":"(Dia lanjut kerja.)"}]},{"v":-10,"label":"\"Ngapain sih sendirian? Bodoh.\"","r":[{"s":"Kalau aku pulang, bibitnya ikut turun ke bawah."}]}]},
{"n":4,"title":"Tawaran Proyek Metrapura","at":"teknik","jam":19,"c":{},"place":"Kantor Konsultan · malam","ajak":"Nanti malam. Jam tujuh. Kantor. Ada surat. Aku pengin kamu baca.","p":[{"act":"(Bekas kantor Arya nawarin jabatan kepala proyek di Metrapura. Gajinya lima kali lipat.)"},{"act":"(Di suratnya tertulis dia \"sudah dimaafkan\". Arya nyodorin surat itu tanpa ngomong apa-apa.)"}],"ask":"Arya nunggu pendapatmu soal surat itu. Kamu bilang apa?","o":[{"v":15,"label":"\"Aku dukung apa pun pilihanmu. Tapi kamu nggak salah apa-apa, jadi nggak ada yang perlu dimaafin.\"","r":[{"act":"(Dia merobek surat itu jadi dua.)"},{"s":"Aku nunggu orang ngomong gitu lima tahun."}]},{"v":5,"label":"\"Jangan pergi dong.\"","r":[{"act":"(Dia senyum kecil.)"},{"s":"Nggak pergi, kok."},{"act":"(Tapi masih kelihatan ragu.)"}]},{"v":-10,"label":"\"Ambil aja, gajinya gede.\"","r":[{"s":"Iya. Mungkin."},{"act":"(Seminggu kemudian dia menolaknya sendiri, tanpa cerita ke kamu.)"}]}]},
{"n":5,"title":"Rumah yang Dia Gambar","at":"lereng.bukit","jam":20,"c":{},"place":"Bukit Bintang · malam","ajak":"Jam delapan malam. Bukit Bintang. Bawa jaket. Anginnya dua belas knot.","p":[{"act":"(Arya membuka halaman terakhir buku sketsanya. Rumah dengan kebun herba dan jendela menghadap bukit.)"},{"s":"Aku nggak sadar ini buat siapa. Sampai Sekar nanya minggu lalu, 'Ini rumahnya Dokter, ya?'"}],"ask":"Arya nunjukin rumah yang dia gambar. Kamu jawab apa?","o":[{"v":15,"label":"\"Jendelanya harus dua. Satu buat kamu, satu buat aku.\"","r":[{"act":"(Dia ketawa keras. Pertama kalinya di depanmu.)"}]},{"v":5,"label":"\"Ini buat aku? …Iya. Iya, aku mau.\"","r":[{"act":"(Dia membetulkan kacamata tiga kali berturut-turut.)"}]},{"v":-10,"label":"\"Ini rumah siapa, sih?\"","r":[{"act":"(Dia menutup buku itu pelan-pelan.)"}]}]}],"raka":[{"n":1,"title":"Tilang Sepeda","at":"niaga.janji","jam":20,"c":{},"place":"Jalan Niaga · malam","ajak":"Dok, malam ini jam delapan lewat Jalan Niaga, ya. Ada razia. Razia khusus. Pesertanya satu orang. Hehe.","p":[{"act":"(Kamu nuntun sepeda ontel tua Om Darto. Raka nyetop kamu sambil niup peluit.)"},{"s":"Selamat malam. Sepedanya nggak ada lampu, ya? Hmm. Ini harus ditilang."},{"act":"(Dia nyerahin surat tilang. Pelanggarannya: \"senyum kemanisan tanpa izin\".)"}],"ask":"Raka nilang kamu karena senyum kemanisan. Kamu ngapain?","o":[{"v":15,"label":"(Tulis \"surat banding\" di baliknya: \"Terdakwa siap dihukum traktir gorengan.\")","r":[{"act":"(Dia terbahak.)"},{"s":"Banding diterima! Sidang di angkringan, jam tujuh."}]},{"v":5,"label":"(Ketawa, lalu simpan suratnya.)","r":[{"s":"Disimpan, ya. Itu barang bukti."}]},{"v":-10,"label":"\"Nggak lucu. Aku capek.\"","r":[{"s":"Siap. Maaf, Dok."},{"act":"(Dia memberi hormat dengan kaku.)"}]}]},
{"n":2,"title":"Patroli Malam","at":"alun.plaza","jam":21,"c":{},"place":"Alun-alun ke Jalan Niaga · jam sembilan malam","ajak":"Dok, ikut patroli, yuk? Jam sembilan, kumpul di Alun-alun. Seragam nggak wajib. Senter wajib. Nanti aku pinjemin.","p":[{"act":"(Kalian ngecek gembok toko, nyapa Pak Slamet, dan betulin lampu jalan yang kedip-kedip.)"},{"s":"Kota ini tenang banget, ya. Kadang aku bingung harus diapain rasa tenang ini. Di Metrapura nggak pernah ada."}],"ask":"Raka bingung sama kota yang terlalu tenang. Kamu jawab apa?","o":[{"v":15,"label":"\"Kamu bukan polisi lembek. Kamu polisi yang mau dengerin.\"","r":[{"s":"Siapa yang bilang aku lembek?"},{"s":"Mukamu.","who":"me"},{"act":"(Dia ketawa sampai harus berhenti jalan.)"}]},{"v":5,"label":"\"Tenang kan enak.\"","r":[{"s":"Iya, ya."},{"act":"(Dia senyum. Masih ada yang belum dia ceritakan.)"}]},{"v":-10,"label":"\"Ya kalau bosen, pindah aja.\"","r":[{"s":"Ha. Kamu kok kedengeran kayak bapakku."}]}]},
{"n":3,"title":"Menyelidiki Pak Joni","at":"polisi","jam":12,"c":{},"place":"Pos Polisi · siang","ajak":"Dok, siang ini mampir Pos, ya? Jam dua belas. Ada laporan warga. Aku butuh keterangan ahli. Ahlinya kamu.","p":[{"act":"(Ada laporan soal tambal gigi tanpa alat steril. Pelakunya Pak Joni, tukang gigi keliling.)"},{"s":"Secara medis bahaya, aku ngerti. Tapi dia juga orang kecil yang lagi cari makan. Gimana, Dok?"}],"ask":"Raka minta pendapatmu soal Pak Joni. Kamu jawab apa?","o":[{"v":15,"label":"\"Praktiknya kita hentikan, tapi kita bantu dia cari kerja lain.\"","r":[{"s":"Nah. Pagar yang nggak bikin orang jatuh."}]},{"v":5,"label":"\"Tangkap aja, dia bahaya.\"","r":[{"s":"Bisa. Tapi aku pernah salah pakai cara itu."},{"act":"(Dia tetap menjalankannya.)"}]},{"v":-10,"label":"\"Itu urusanmu, bukan urusanku.\"","r":[{"s":"…Siap."},{"act":"(Dia menyelesaikannya sendirian. Jadi lebih lama.)"}]}]},
{"n":4,"title":"Luka Saat Tugas","at":"klinik","jam":16,"c":{},"place":"Klinik · sore","ajak":"Dok, nanti sore aku mampir, ya. Jam empat. Nggak ada apa-apa. Cuma… mau mampir. Itu aja. Beneran.","p":[{"act":"(Raka datang sambil megangin bibir. Robek. Gigi seri atasnya patah sedikit. Dia jatuh waktu ngejar pencuri motor.)"},{"s":"Jangan ke Puskesmas, Dok. Masa polisi ompong diperiksa bidan. Malu sama bayi-bayi."},{"act":"(Kamu merapikan giginya. Di sela sakit dia masih sempat melawak.)"}],"ask":"Raka masih ngelawak padahal kesakitan. Kamu bilang apa?","o":[{"v":15,"label":"\"Sekarang kamu nggak usah bikin aku ketawa. Kamu boleh kesakitan.\"","r":[{"act":"(Dia diam.)"},{"s":"…Dulu aku pernah dirawat di rumah sakit. Bapak nggak pernah dateng."}]},{"v":5,"label":"\"Untung cuma gigi.\"","r":[{"s":"Untung dokternya kamu."},{"act":"(Lalu dia balik bercanda.)"}]},{"v":-10,"label":"\"Ngapain ngejar sendirian? Ceroboh.\"","r":[{"s":"Iya, iya. Laporan diterima."},{"act":"(Dia menutup diri.)"}]}]},
{"n":5,"title":"Lencana Kedua","at":"lereng.bukit","jam":20,"c":{},"place":"Bukit Bintang · malam","ajak":"Dok. Malam ini jam delapan, Bukit Bintang. Ini perintah. Eh, bukan. Permohonan. Permohonan resmi.","p":[{"act":"(Raka ngeluarin dua lencana. Miliknya yang sekarang, dan lencana pertamanya dari akademi.)"},{"act":"(Yang kedua dia sematkan di jas putihmu.)"},{"s":"Ini udah jagain aku sepuluh tahun. Sekarang gantian. Aku yang jagain kamu."}],"ask":"Raka nyematin lencananya di jasmu. Kamu jawab apa?","o":[{"v":15,"label":"(Kasih hormat.) \"Siap, Komandan. Laporan: aku juga sayang kamu.\"","r":[{"act":"(Dia ketawa sambil nutup mata pakai tangan.)"}]},{"v":5,"label":"\"Ini beneran? …Iya.\"","r":[{"s":"Lencananya jangan dijual di Warung, ya."}]},{"v":-10,"label":"\"Ini bercanda lagi, kan?\"","r":[{"act":"(Dia mengambil lencananya kembali pelan-pelan.)"}]}]}],"galih":[{"n":1,"title":"Pasien Rujukan Bersama","at":"klinik","jam":12,"c":{},"place":"Klinik · siang","ajak":"Dokter, siang ini saya antar pasien rujukan ke klinik, jam dua belas. Pak Hasan, hipertensi. Saya ikut, kalau boleh.","p":[{"act":"(Galih mengantar sendiri Pak Hasan. Surat rujukannya rapi sekali. Tulisannya bisa dibaca. Langka untuk dokter.)"},{"s":"Sebelum tindakan, boleh kita ukur tensinya bersama? Saya biasa cek dua kali. Maaf kalau merepotkan."}],"ask":"Galih minta ngecek tensi bareng. Kamu jawab apa?","o":[{"v":15,"label":"\"Surat rujukanmu paling rapi yang pernah aku baca. Cek dua kali bareng, yuk?\"","r":[{"act":"(Dia tersenyum tipis.)"},{"s":"Akhirnya ada yang tidak menganggap itu aneh."}]},{"v":5,"label":"\"Makasih rujukannya.\"","r":[{"act":"(Dia tetap ramah dan profesional. Obrolannya singkat.)"}]},{"v":-10,"label":"\"Nggak usah repot cek tensi, aku bisa sendiri.\"","r":[{"s":"Tentu. Maaf."},{"act":"(Dia pamit dengan kaku.)"}]}]},
{"n":2,"title":"Jaga Malam","at":"puskes","jam":21,"c":{"hari":[1,4]},"place":"Puskesmas · jaga malam","ajak":"Malam ini saya jaga di Puskesmas. Kalau Dokter belum mengantuk jam sembilan, mampir. Tehnya ada dua gelas.","p":[{"act":"(Puskesmas sepi. Cuma ada Galih dan tehnya yang sudah dingin. Dia menuangkan segelas lagi untukmu.)"},{"s":"Boleh saya tanya? Kenapa dulu Dokter memilih jadi dokter gigi?"}],"ask":"Galih nanya alasanmu jadi dokter. Kamu jawab apa?","o":[{"v":15,"label":"(Jujur soal capek dan burnout waktu kerja di Metrapura.)","r":[{"act":"(Dia mendengarkan, lalu bercerita sedikit.)"},{"s":"Sepertinya kita kabur dari kota yang sama."}]},{"v":5,"label":"(Ngobrol soal pasien dan kerjaan saja.)","r":[{"act":"(Obrolannya enak, tapi nggak pernah dalam.)"}]},{"v":-10,"label":"\"Kamu kok kelihatan sedih terus, sih?\"","r":[{"s":"Oh. Begitu, ya."},{"act":"(Dia menunduk ke gelasnya.)"}]}]},
{"n":3,"title":"Pasien yang Tak Tertolong","at":"puskes","jam":8,"c":{"hujan":1},"place":"Puskesmas · pagi setelah hujan","ajak":"Besok pagi, kalau Dokter sempat, jam delapan ke Puskesmas. Tidak ada apa-apa. Saya cuma… ingin ada teman.","p":[{"act":"(Semalam seorang kakek dari Dusun Atas meninggal karena gagal jantung di perjalanan ke Puskesmas.)"},{"act":"(Kamu menemukan Galih di tangga belakang. Duduk, diam, masih pakai jas.)"}],"ask":"Galih duduk diam di tangga. Kamu ngapain?","o":[{"v":15,"label":"(Duduk di sebelahnya. Nggak ngasih nasihat. Nunggu sampai dia mau ngomong.)","r":[{"s":"Di Metrapura saya pernah salah dosis. Karena lelah. Saya belum pernah cerita ke siapa pun."}]},{"v":5,"label":"\"Itu bukan salahmu.\"","r":[{"s":"Saya tahu."},{"act":"(Dia berterima kasih, tapi masih menyimpan sesuatu.)"}]},{"v":-10,"label":"\"Namanya juga dokter, pasti pernah gagal.\"","r":[{"s":"…Iya."},{"act":"(Kalimatnya benar, tapi datang terlalu cepat. Dia berdiri dan masuk.)"}]}]},
{"n":4,"title":"Beda Pendapat Antibiotik","at":"klinik","jam":13,"c":{},"place":"Klinik · siang","ajak":"Siang ini saya ke klinik, jam satu. Soal Mas Rudi, absesnya. Saya ingin kita sepakat dulu sebelum resep keluar.","p":[{"act":"(Galih ingin menahan antibiotik supaya tidak memicu resistensi. Kamu lihat bengkaknya harus segera ditangani.)"},{"s":"Dokter, antibiotik bukan permen. Kalau setiap bengkak kita beri, lima tahun lagi obatnya tidak mempan."}],"ask":"Diskusinya mulai panas. Kamu bilang apa?","o":[{"v":15,"label":"\"Drainase dulu, antibiotik sesuai indikasi, terus kita pantau tiga hari. Kita dua-duanya bener.\"","r":[{"act":"(Dia tertawa kecil.)"},{"s":"Biasanya debat seperti ini saya kalah sama diri sendiri."}]},{"v":5,"label":"\"Ya udah, terserah kamu.\"","r":[{"s":"Saya tidak senang menang begini. Saya ingin Dokter debat."}]},{"v":-10,"label":"\"Aku dokter giginya. Ini pasienku.\"","r":[{"s":"Betul."},{"act":"(Dia pergi, lebih dingin dari biasanya.)"}]}]},
{"n":5,"title":"Catatan di Kertas Resep","at":"lereng.bukit","jam":20,"c":{},"place":"Bukit Bintang · malam","ajak":"Dokter, malam ini jam delapan, saya tunggu di Bukit Bintang. Ada yang ingin saya serahkan. Bukan rujukan.","p":[{"act":"(Galih menyerahkan selembar kertas resep.)"},{"act":"(Isinya: \"R/ Kamu. Dosis: setiap hari. Seumur hidup. Efek samping: senyum.\")"},{"act":"(Di baliknya ada puisi tentang dokter gigi yang datang ke kota sepi.)"}],"ask":"Galih nunggu jawabanmu soal resep itu. Kamu ngapain?","o":[{"v":15,"label":"(Tulis balasan di kertas resepmu sendiri: \"Resep diterima. Kontrol rutin.\")","r":[{"act":"(Dia akhirnya tertawa lepas.)"}]},{"v":5,"label":"\"Ini kamu yang nulis?\" \"…Iya.\" \"Aku mau.\"","r":[{"act":"(Dia menutup wajah pakai tangan. Lega.)"}]},{"v":-10,"label":"\"Tulisanmu rapi banget, nggak kayak dokter.\"","r":[{"act":"(Dia melipat kertas itu pelan-pelan.)"}]}]}],"sekar":[{"n":1,"title":"Buku Telat","at":"klinik","jam":16,"c":{},"place":"Klinik · sore","ajak":"Dokter… nanti jam empat saya mampir ke klinik, boleh? Ada… urusan kecil. Kecil sekali. Soal buku.","p":[{"act":"(Buku yang kamu pinjam udah telat tiga hari.)"},{"act":"(Sekar datang sendiri, tapi terlalu malu buat bilang. Lima belas menit dia pura-pura baca poster sikat gigi.)"},{"s":"Eh… itu… bukunya… kalau sudah selesai… nggak buru-buru, kok. Beneran."}],"ask":"Sekar dateng nagih buku yang telat. Kamu ngapain?","o":[{"v":15,"label":"(Balikin bukunya dan bilang bab mana yang paling kamu suka.)","r":[{"act":"(Matanya berbinar.)"},{"s":"Bab itu juga favorit saya. Saya kira cuma saya."}]},{"v":5,"label":"\"Maaf ya, telat. Dendanya berapa?\"","r":[{"s":"Nggak ada denda, kok."},{"act":"(Dia tersenyum kecil, lalu pulang.)"}]},{"v":-10,"label":"\"Buku apa, ya? Aku lupa.\"","r":[{"s":"Oh. Nggak apa-apa."},{"act":"(Dia pulang. Bukunya tetap ketinggalan di klinik.)"}]}]},
{"n":2,"title":"Bunga Favorit","at":"lereng.bunga","jam":7,"c":{},"place":"Kebun Bunga · pagi","ajak":"Besok pagi jam tujuh… telangnya mekar. Kalau Dokter mau lihat… di kebun. Kalau nggak sibuk.","p":[{"act":"(Sekar lagi nyiram bunga. Dia nunjukin bunga telang dan cara nyeduhnya sampai airnya biru.)"},{"s":"Kalau dikasih jeruk nipis, airnya jadi ungu. Kayak sulap. Anak-anak SD suka sekali."},{"act":"(Waktu kamu tanya bunga favoritnya, dia ragu.)"}],"ask":"Sekar ragu nyebut bunga favoritnya. Kamu bilang apa?","o":[{"v":15,"label":"\"Kalau aku tebak: telang. Kamu ceritanya paling panjang waktu ngomongin itu.\"","r":[{"act":"(Dia tertawa kecil dan nutup mulut.)"},{"s":"Ketahuan, ya."}]},{"v":5,"label":"\"Bunganya cantik semua.\"","r":[{"s":"Makasih."},{"act":"(Dia ngasih kamu satu tangkai.)"}]},{"v":-10,"label":"\"Aku nggak terlalu ngerti bunga, sih.\"","r":[{"s":"Oh, iya. Nggak apa-apa."},{"act":"(Dia lanjut nyiram tanpa bicara.)"}]}]},
{"n":3,"title":"Bibit untuk Lereng","at":"lereng.bunga","jam":7,"c":{"hujan":1},"place":"Kebun Bunga · pagi, Musim Hujan","ajak":"Besok pagi… jam tujuh… bibit buat Tanam Pohon Bersama siap. Kalau Dokter mau lihat. Ratusan, lho.","p":[{"act":"(Angin dan hujan semalam merobohkan rak bibit Sekar.)"},{"act":"(Dia berlutut di tanah basah, mindahin bibit ke polybag satu per satu. Orang lewat mau bantu, dia tolak.)"}],"ask":"Sekar berlutut di tanah basah sendirian. Kamu ngapain?","o":[{"v":15,"label":"(Ikut berlutut tanpa nanya, lalu pindahin bibit ke polybag baru.)","r":[{"s":"Bibit ini dari Tante Lies. Makasih udah nggak bilang 'nanti tanam lagi aja'."}]},{"v":5,"label":"(Bawain payung dan teh hangat.)","r":[{"s":"Makasih, Dokter."},{"act":"(Dia tetap kerja sendirian.)"}]},{"v":-10,"label":"\"Ya udah, nanti tanam lagi aja.\"","r":[{"s":"Iya."},{"act":"(Dia menunduk lebih dalam ke bibitnya.)"}]}]},
{"n":4,"title":"Naskah Ditolak","at":"perpus","jam":16,"c":{},"place":"Perpustakaan · sore","ajak":"Dokter… sore ini jam empat… bisa ke Perpustakaan? Ada surat. Saya… belum berani buka sendiri.","p":[{"act":"(Mas Ilham baru ngantar surat dari penerbit Metrapura. Naskah novel Sekar ditolak.)"},{"s":"Saya… yang nulis cerpen di koran pakai nama Telang. Itu saya. Nggak ada yang tahu. Sekarang Dokter tahu."}],"ask":"Sekar ngaku dia \"Telang\", dan naskahnya ditolak. Kamu bilang apa?","o":[{"v":15,"label":"\"Boleh aku baca naskahnya? Bukan karena kasihan. Aku pengin tahu ceritanya.\"","r":[{"act":"(Dia ngasih naskahnya. Tangannya gemetar. Seminggu kemudian dia kirim ke penerbit lain.)"}]},{"v":5,"label":"\"Penerbitnya aja yang nggak ngerti.\"","r":[{"s":"Makasih."},{"act":"(Tapi naskahnya dia simpan lagi di laci.)"}]},{"v":-10,"label":"\"Mungkin coba nulis yang lebih rame?\"","r":[{"act":"(Dia mengangguk pelan.)"},{"s":"Iya. Terlalu sepi, ya."}]}]},
{"n":5,"title":"Bunga di Buku","at":"lereng.bukit","jam":20,"c":{},"place":"Bukit Bintang · malam","ajak":"Dokter… malam ini jam delapan… Bukit Bintang. Saya mau minjemin buku. Bacanya harus di sana. Nanti tahu kenapa.","p":[{"s":"Bacanya di sini aja. Sekarang. Saya… lihat bintang dulu."},{"act":"(Di halaman tengah ada bunga telang kering yang dipres, dan secarik kertas bertulisan tangannya.)"},{"act":"(\"Ini cerita yang belum pernah aku tulis. Tentang aku yang suka sama kamu.\")"}],"ask":"Kamu nemu surat Sekar di dalam buku. Kamu ngapain?","o":[{"v":15,"label":"(Tulis jawaban di balik kertas itu, lalu selipkan lagi di halaman yang sama.)","r":[{"act":"(Dia membacanya, menutup buku, lalu memeluknya erat.)"}]},{"v":5,"label":"\"Ini… buat aku? Aku juga suka kamu.\"","r":[{"act":"(Mukanya merah sampai telinga.)"}]},{"v":-10,"label":"\"Ini bukunya bagus, tapi bunganya jatuh.\"","r":[{"act":"(Dia memungut bunga itu pelan-pelan.)"}]}]}],"nadia":[{"n":1,"title":"Racikan Baru","at":"kedai","jam":16,"c":{},"place":"Kedai Kopi Seduh · sore","ajak":"Dok! Dok! Sore ini jam empat ke kedai, ya! Aku punya racikan baru. Kamu kelinci percobaan pertama. Kehormatan, lho!","p":[{"act":"(Nadia nyodorin kopi serai. Dia ngelihatin kamu nyeruput. Nggak kedip.)"},{"s":"Gimana? Gimana? Jujur. Eh, jangan jujur-jujur amat. Eh, jujur aja deh. Gimana?"}],"ask":"Nadia nunggu pendapatmu soal kopi serai. Kamu bilang apa?","o":[{"v":15,"label":"\"Serainya enak, tapi kopinya kalah. Kurangi serainya sedikit.\"","r":[{"act":"(Dia langsung nyatet.)"},{"s":"Akhirnya ada yang jujur! Mas Adji bilang semuanya enak."}]},{"v":5,"label":"\"Enak!\"","r":[{"s":"Beneran? Beneran enak?"},{"act":"(Dia senang, tapi tetap ragu.)"}]},{"v":-10,"label":"\"Aku lebih suka kopi biasa.\"","r":[{"s":"Oh. Oke, kopi biasa."},{"act":"(Senyumnya mengecil.)"}]}]},
{"n":2,"title":"Kopi Spesial","at":"kedai","jam":21,"c":{},"place":"Kedai Kopi Seduh · malam, sebelum tutup","ajak":"Dok, nanti jam sembilan mampir pas kedai sepi, ya. Ada yang mau aku seduhin. Nggak dijual. Jangan bilang siapa-siapa.","p":[{"act":"(Kedai sepi. Nadia menyeduh biji terbaik dari Pak Bowo. Satu-satunya kantong yang nggak dia jual.)"},{"s":"Ini buat orang yang aku anggap spesial. Jangan geer! Mas Adji juga pernah, kok."},{"act":"(Adji belum pernah.)"}],"ask":"Nadia nyeduhin kopi spesialnya. Kamu ngapain?","o":[{"v":15,"label":"(Tanya soal bijinya: dari petak mana, kapan dipetik.)","r":[{"act":"(Matanya nyala. Dia cerita soal pagi-pagi di kebun Pak Bowo, lalu sadar udah bocorin rahasia.)"}]},{"v":5,"label":"\"Wah, makasih. Enak banget.\"","r":[{"act":"(Dia senyum lebar, lalu ngelap meja.)"}]},{"v":-10,"label":"(Tambahin gula dua sendok sebelum nyicip.)","r":[{"s":"…Oke."},{"act":"(Dia nyatet sesuatu di bukunya. Bukan pujian.)"}]}]},
{"n":3,"title":"Kedai Sepi","at":"kedai","jam":16,"c":{"hujan":1},"place":"Kedai Kopi Seduh · sore, Musim Hujan","ajak":"Dok… sore ini jam empat mampir, ya? Kedai sepi. Nggak apa-apa. Aku cuma pengin ada yang dateng aja.","p":[{"act":"(Hujan tiga hari. Kedai kosong.)"},{"act":"(Kamu nemuin Nadia duduk di lantai belakang meja bar, sama buku kas dan kalkulator. Matanya merah.)"},{"s":"Eh, Dok! Hehe. Aku lagi… ngitung. Ngitung doang. Kok mukamu gitu? Aku nggak apa-apa. Serius."}],"ask":"Nadia duduk di lantai, matanya merah. Kamu ngapain?","o":[{"v":15,"label":"(Duduk di lantai sebelahnya.) \"Nggak usah semangat dulu. Aku temenin aja.\"","r":[{"act":"(Dia bersandar ke bahumu, lalu cerita soal pinjaman dan orang tuanya.)"}]},{"v":5,"label":"\"Ayo kita pikirin promo.\"","r":[{"act":"(Dia langsung bangkit dan semangat lagi. Lukanya belum kesentuh.)"}]},{"v":-10,"label":"\"Mungkin emang kota ini terlalu kecil buat kedai kayak gini.\"","r":[{"act":"(Dia diam.)"},{"s":"Itu juga kata Mama."}]}]},
{"n":4,"title":"Pemasok","at":"lereng.kopi","jam":12,"c":{},"place":"Kebun Kopi · siang","ajak":"Dok, siang ini jam dua belas ke Kebun Kopi, ya? Aku butuh saksi. Atau pelerai. Pokoknya butuh kamu.","p":[{"act":"(Seorang tengkulak nawarin biji murah ke Nadia. Separuh harga Pak Bowo, kualitasnya di bawah.)"},{"act":"(Pak Bowo tahu dan marah besar. Nadia kejepit di tengah.)"},{"s":"Kedaiku harus hemat, Dok. Tapi Pak Bowo… yang ngajarin aku nyangrai. Aku harus gimana?"}],"ask":"Nadia kejepit antara hemat dan Pak Bowo. Kamu bilang apa?","o":[{"v":15,"label":"\"Ngomong jujur sama Pak Bowo. Bilang kamu butuh waktu bayar, bukan biji yang lebih murah.\"","r":[{"s":"Wis, bayar kalau kedaimu rame.","who":"bowo"},{"act":"(Nadia memeluknya. Pak Bowo kaku kayak tiang.)"}]},{"v":5,"label":"\"Ambil yang murah dulu, sementara.\"","r":[{"act":"(Dia coba seminggu, lalu balik ke Pak Bowo sambil malu.)"}]},{"v":-10,"label":"\"Itu urusan bisnis, jangan bawa perasaan.\"","r":[{"s":"Iya, Dok. Bisnis."},{"act":"(Dia jadi dingin ke kamu beberapa hari.)"}]}]},
{"n":5,"title":"Kopi Tanpa Nama","at":"lereng.bukit","jam":20,"c":{},"place":"Bukit Bintang · malam","ajak":"Dok, malam ini jam delapan, Bukit Bintang. Aku bawa termos. Jangan telat, nanti kopinya dingin. Dan aku juga.","p":[{"act":"(Nadia bawa termos dan dua cangkir. Racikan baru, dibuat khusus buat kamu selama sebulan.)"},{"s":"Belum ada namanya. Aku mau kamu yang kasih nama. Soalnya ini… rasanya kayak aku kalau di dekat kamu."}],"ask":"Nadia minta kamu ngasih nama racikannya. Kamu jawab apa?","o":[{"v":15,"label":"(Kasih nama sesuai tempat kalian pertama kali ngobrol lama.)","r":[{"act":"(Dia nulis nama itu di termos pakai spidol, lalu ketawa sambil nangis.)"}]},{"v":5,"label":"\"Namanya 'Nadia'. Soalnya enak.\"","r":[{"s":"Gombal banget. Tapi oke, aku terima."}]},{"v":-10,"label":"\"Kopi Senyum aja, biar sama kayak klinik.\"","r":[{"act":"(Dia tersenyum tipis.)"},{"s":"Bagus juga."}]}]}],"laras":[{"n":1,"title":"Foto Candid","at":"klinik","jam":12,"c":{},"place":"Klinik · siang","ajak":"Dok! Siang ini jam dua belas aku ke klinik, ya! Ada yang mau aku tunjukin. Jangan marah duluan. Janji, ya?","p":[{"act":"(Laras datang bawa cetakan foto. Kamu, lewat jendela klinik, lagi nenangin pasien anak.)"},{"s":"Maaf! Aku motret diam-diam. Tapi lihat deh. Muka Dokter waktu sabar itu bagus banget. Sumpah."}],"ask":"Laras motret kamu diam-diam. Kamu bilang apa?","o":[{"v":15,"label":"\"Ini bagus. Boleh aku pajang di ruang tunggu?\"","r":[{"act":"(Dia melongo, lalu lompat kecil.)"},{"s":"Fotoku dipajang di klinik? Serius?"}]},{"v":5,"label":"\"Wah, makasih. Lain kali bilang dulu, ya.\"","r":[{"s":"Siap! Mungkin."},{"act":"(Dia nyengir.)"}]},{"v":-10,"label":"\"Kok motret orang diam-diam, sih?\"","r":[{"s":"Maaf… iya, harusnya izin dulu."},{"act":"(Dia menyobek cetakannya di depanmu.)"}]}]},
{"n":2,"title":"Pameran Gagal","at":"studio","jam":16,"c":{},"place":"Studio Foto Lensa · sore","ajak":"Dok, sore ini jam empat main ke studio, yuk? Lagi berantakan sih. Banget. Tapi nggak apa-apa, kan? Hahaha.","p":[{"act":"(Pameran pertama Laras di galeri kecil Tanjung Arum batal seminggu sebelum buka. Galerinya tutup.)"},{"act":"(Bingkai foto numpuk di studio. Laras bercanda soal itu. Terlalu banyak.)"},{"s":"Hahaha, ya udah lah ya. Bingkainya bisa buat jemuran. Atau talenan. Talenan mahal, lho!"}],"ask":"Laras bercanda terus soal pameran yang batal. Kamu bilang apa?","o":[{"v":15,"label":"\"Ayo kita lihat satu-satu. Aku jadi pengunjung pertamanya.\"","r":[{"act":"(Dia diam, lalu menyusun bingkai di lantai. Pameran untuk satu orang.)"}]},{"v":5,"label":"\"Nanti pasti ada kesempatan lain.\"","r":[{"s":"Iya, pasti!"},{"act":"(Senyumnya nggak sampai ke mata.)"}]},{"v":-10,"label":"\"Ya udah, galerinya juga kecil, kan?\"","r":[{"s":"Iya. Kecil."},{"act":"(Dia mulai membungkus bingkainya lagi.)"}]}]},
{"n":3,"title":"Pameran Foto Warga","at":"alun.plaza","jam":16,"c":{},"place":"Alun-alun · sore","ajak":"Dok! Sore ini jam empat ke Alun-alun! Aku bikin pameran sendiri! Pakai tali jemuran! Jangan ketawa!","p":[{"act":"(Potret warga Rimbasari dijepit di tali jemuran keliling Alun-alun. Bu Ratna nangis lihat fotonya sendiri.)"},{"act":"(Ada satu tali yang kosong.)"},{"s":"Itu buat foto yang belum ada. Nanti. Kapan-kapan. Hehe."}],"ask":"Ada satu tali kosong di pameran Laras. Kamu ngapain?","o":[{"v":15,"label":"(Ambil kameranya, potret Laras di depan pamerannya, lalu jepit fotonya di tali kosong.)","r":[{"act":"(Dia nutup muka, lalu ketawa.)"},{"s":"Curang. Itu fotoku yang pertama setelah sepuluh tahun."}]},{"v":5,"label":"(Puji pamerannya di depan warga.)","r":[{"act":"(Dia tersipu dan sibuk berterima kasih ke semua orang.)"}]},{"v":-10,"label":"\"Kok fotomu sendiri nggak ada?\"","r":[{"s":"Nggak mau."},{"s":"Ya udah.","who":"me"},{"act":"(Tali kosong itu tetap kosong.)"}]}]},
{"n":4,"title":"Tawaran Metrapura","at":"studio","jam":20,"c":{},"place":"Studio Foto Lensa · malam","ajak":"Dok… malam ini jam delapan ke studio, ya? Aku dapet email. Gede. Aku bingung. Bingung banget.","p":[{"act":"(Majalah besar di Metrapura nawarin Laras jadi fotografer tetap, gara-gara foto Pameran Warga viral.)"},{"s":"Bapak bilang berangkat aja. Katanya kapan lagi. Tapi… aku nggak tahu, Dok."}],"ask":"Laras bingung soal tawaran Metrapura. Kamu bilang apa?","o":[{"v":15,"label":"\"Kenapa nggak dua-duanya? Kirim foto Rimbasari ke mereka, tapi kamu tetap di sini.\"","r":[{"act":"(Besoknya dia ngusulin rubrik bulanan \"Kota Kecil\", dikirim dari Rimbasari.)"}]},{"v":5,"label":"\"Jangan pergi, ya.\"","r":[{"s":"Siapa yang mau pergi?"},{"act":"(Dia ketawa, tapi masih ragu.)"}]},{"v":-10,"label":"\"Ambil aja, di sini kan nggak ada apa-apa.\"","r":[{"s":"Ada, kok."},{"act":"(Dia diam lama, lalu memutuskan sendiri.)"}]}]},
{"n":5,"title":"Foto Berdua","at":"lereng.bukit","jam":20,"c":{},"place":"Bukit Bintang · malam","ajak":"Dok, malam ini jam delapan, Bukit Bintang. Bawa muka terbaikmu. Eh, muka biasa juga udah bagus. Pokoknya dateng.","p":[{"act":"(Laras masang tripod dan nyetel timer sepuluh detik.)"},{"s":"Aku belum pernah foto berdua sama siapa pun. Mau yang pertama?"},{"act":"(Lampu timer kedip. Di detik ketiga dia ngomong cepat banget: \"Akusukasamakamu.\" Klik.)"}],"ask":"Laras ngomong cepat banget sebelum kamera bunyi. Kamu ngapain?","o":[{"v":15,"label":"\"Ulang. Aku belum jawab di fotonya.\" (Setel timer lagi.)","r":[{"act":"(Foto kedua: dua-duanya ketawa. Laras nggak nutup mulut.)"}]},{"v":5,"label":"\"Aku juga.\"","r":[{"act":"(Fotonya buram karena Laras lompat.)"}]},{"v":-10,"label":"\"Hah? Tadi ngomong apa?\"","r":[{"s":"Bukan apa-apa! Fotonya bagus, kok."}]}]}],"wulan":[{"n":1,"title":"Persalinan Malam","at":"puskes","jam":21,"c":{},"place":"Puskesmas · malam","ajak":"Dok, malam ini saya jaga. Ada ibu dari Kampung Kali, kayaknya lahiran malam ini. Kalau lewat jam sembilan, mampir.","p":[{"act":"(Galih lagi jaga di desa lain. Wulan sendirian bantu persalinan darurat.)"},{"s":"Dok! Syukur. Tolong pegang lampu ini. Tinggi sedikit. Ya, gitu. Jangan goyang, ya."},{"act":"(Kamu pegang lampu, siapin air, nenangin suami si ibu. Bayinya lahir selamat.)"}],"ask":"Bayinya lahir selamat. Kamu ngapain?","o":[{"v":15,"label":"(Ikuti semua instruksinya, lalu bikinin dia teh.)","r":[{"s":"Dokter gigi pegang lampu paling stabil yang pernah saya lihat."},{"act":"(Dia nulis namamu di samping nama bayi itu.)"}]},{"v":5,"label":"(Bantu, lalu langsung pamit karena capek.)","r":[{"s":"Makasih banyak, Dok."},{"act":"(Dia kembali ke ibu dan bayinya.)"}]},{"v":-10,"label":"\"Aku dokter gigi, bukan bidan.\"","r":[{"s":"Betul. Maaf, Dok."},{"act":"(Dia manggil suami si ibu buat pegang lampu.)"}]}]},
{"n":2,"title":"Imunisasi","at":"sd","jam":8,"c":{},"place":"SD Negeri · pagi","ajak":"Dok, besok pagi jam delapan imunisasi di SD. Saya butuh bala bantuan. Dokter gigi pasti punya jurus, kan?","p":[{"act":"(Separuh kelas nangis. Dimas sembunyi di bawah meja.)"},{"s":"Dok, tolong. Saya suntik, Dokter yang… pokoknya bikin mereka lupa ada jarum."}],"ask":"Separuh kelas nangis. Kamu ngapain?","o":[{"v":15,"label":"(Ajak anak-anak ngitung gigi teman sebelahnya selama Wulan nyuntik.)","r":[{"act":"(Kelas ketawa. Wulan selesai dua kali lebih cepat.)"},{"s":"Jurusnya saya curi, ya."}]},{"v":5,"label":"(Pegang tangan anak satu per satu.)","r":[{"act":"(Berhasil, tapi lama. Wulan tetap berterima kasih.)"}]},{"v":-10,"label":"\"Wah, aku juga nggak bisa ngurus anak nangis.\"","r":[{"act":"(Dia ngurus sendiri dan memaklumi. Senyumnya kecil.)"}]}]},
{"n":3,"title":"Jaga 24 Jam","at":"puskes","jam":12,"c":{},"place":"Puskesmas · siang","ajak":"Dok, kalau siang ini lewat Puskesmas, jam dua belas… bawain apa aja yang bisa dimakan. Nanti saya ganti. Kayaknya.","p":[{"act":"(Wulan udah jaga 24 jam. Dua persalinan, satu demam berdarah. Belum tidur.)"},{"act":"(Kamu datang bawa makanan. Dia ketiduran sambil berdiri di depan lemari obat.)"}],"ask":"Wulan ketiduran sambil berdiri. Kamu ngapain?","o":[{"v":15,"label":"\"Tidur. Aku jagain pintunya. Kalau ada yang darurat, aku bangunin.\"","r":[{"act":"(Dia mau nolak, lalu tidur sebelum kalimatnya selesai. Bangun-bangun ada selimut dan makanan hangat.)"}]},{"v":5,"label":"(Taruh makanan dan suruh dia makan.)","r":[{"act":"(Dia makan cepat sambil kerja. Tetap nggak tidur.)"}]},{"v":-10,"label":"\"Kamu terlalu memaksakan diri, tahu nggak?\"","r":[{"s":"Tahu."},{"act":"(Dia kembali ke lemari obat.)"}]}]},
{"n":4,"title":"Beda Pendapat Rujukan","at":"klinik","jam":11,"c":{},"place":"Klinik · siang","ajak":"Dok, nanti jam sebelas saya antar Bu Yati ke klinik. Hamil trimester satu, giginya sakit. Kita perlu ngomong dulu.","p":[{"act":"(Kamu mau periksa dan tangani. Wulan mau semuanya ditunda sampai trimester kedua.)"},{"s":"Trimester satu itu rawan, Dok. Saya nggak mau ambil risiko apa pun. Apa pun."},{"act":"(Diskusinya memanas. Bu Yati di tengah, bingung.)"}],"ask":"Kamu dan Wulan beda pendapat di depan Bu Yati. Kamu bilang apa?","o":[{"v":15,"label":"\"Rontgen kita lewati. Hari ini cuma tindakan darurat yang aman. Sisanya trimester dua, kamu yang pantau.\"","r":[{"s":"Itu yang saya mau dari tadi. Cuma saya nggak tahu cara ngomongnya."}]},{"v":5,"label":"\"Oke, kita tunda semua.\"","r":[{"act":"(Bu Yati pulang masih sakit. Wulan setuju, tapi kelihatan nggak tenang.)"}]},{"v":-10,"label":"\"Ini wilayahku, Bu Bidan.\"","r":[{"s":"Dan dia pasien saya juga, Dok."},{"act":"(Dia keluar lebih cepat dari biasanya.)"}]}]},
{"n":5,"title":"Jalan Pulang","at":"lereng.bukit","jam":20,"c":{},"place":"Bukit Bintang · malam","ajak":"Dok, malam ini habis jaga… antar saya pulang, ya? Lewat Bukit Bintang. Jam delapan. Iya, muternya jauh. Sengaja.","p":[{"act":"(Rumah dinas Wulan cuma lima puluh langkah di belakang Puskesmas. Kalian malah muter lewat Bukit Bintang.)"},{"act":"(Di atas, dia ngeluarin bukunya dan nunjukin halaman terakhir. Masih kosong.)"},{"s":"Selama ini saya nyatet semua bayi yang saya bantu lahir. Halaman ini buat saya sendiri."},{"s":"Mungkin sekarang. Kalau kamu mau."}],"ask":"Wulan nunjukin halaman terakhir bukunya. Kamu jawab apa?","o":[{"v":15,"label":"\"Mulai sekarang, kamu yang dijagain. Gantian.\"","r":[{"act":"(Dia ketawa kecil, lalu bersandar dan langsung tertidur di bahumu. Lima menit kemudian bangun, malu sekali.)"}]},{"v":5,"label":"\"Aku mau.\"","r":[{"s":"Bagus. Sekarang antar saya pulang beneran. Saya ngantuk."}]},{"v":-10,"label":"\"Kamu capek, kita ngomongin besok aja.\"","r":[{"act":"(Dia menutup bukunya pelan.)"},{"s":"Iya. Besok."}]}]}]};
